from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

CellKey = tuple[int, int]


def accumulate_grid(raw: object) -> dict:
    error = _validate(raw)
    if error is not None:
        return {"ok": False, "error": error}

    grid = raw["grid"]
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    fill_value = raw["fill_value"]
    observations = raw["observations"]
    tolerance = cell_size // 2

    sums: dict[CellKey, int] = {}
    counts: dict[CellKey, int] = {}
    degraded: set[CellKey] = set()
    dropped = 0
    rejected = 0
    saturated = 0

    for obs in observations:
        x, y = obs["x"], obs["y"]
        value = obs["value"]
        quality = obs["quality"]

        if quality < MIN_QUALITY:
            rejected += 1
            continue

        col = _bin(x, cell_size, width, tolerance)
        if col is None:
            dropped += 1
            continue
        row = _bin(y, cell_size, height, tolerance)
        if row is None:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + value
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded.add(key)

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _validate(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return "missing field"

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return "bad grid"
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return "bad grid"

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or isinstance(width, bool) or not 1 <= width <= MAX_DIM:
        return "bad width"
    if not isinstance(height, int) or isinstance(height, bool) or not 1 <= height <= MAX_DIM:
        return "bad height"
    if not isinstance(cell_size, int) or isinstance(cell_size, bool) or cell_size < 1:
        return "bad cell size"
    if not isinstance(raw["fill_value"], int) or isinstance(raw["fill_value"], bool):
        return "bad fill value"

    observations = raw["observations"]
    if not isinstance(observations, list):
        return "bad observations"

    for obs in observations:
        if not isinstance(obs, dict):
            return "bad observation"
        if any(
            name not in obs or not isinstance(obs[name], int)
            for name in ("x", "y", "value", "quality")
        ):
            return "bad observation"
        if not 0 <= obs["quality"] <= 100:
            return "bad observation"
    return None


def _bin(coord: int, cell_size: int, dim: int, tolerance: int) -> int | None:
    if coord < 0:
        return None
    index = coord // cell_size
    if index >= dim:
        if coord - dim * cell_size < tolerance:
            return dim - 1
        return None
    return index


def _averaged_rows(sums: dict[CellKey, int], counts: dict[CellKey, int], width: int, height: int, fill_value: int) -> list[list[int]]:
    rows: list[list[int]] = []
    for row in range(height):
        cells: list[int] = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict[CellKey, int], degraded: set[CellKey], width: int, height: int) -> list[list[str]]:
    rows: list[list[str]] = []
    for row in range(height):
        flags: list[str] = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict[CellKey, int], width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

_REQUIRED_FIELDS = ("grid", "observations", "fill_value")
_GRID_FIELDS = ("width", "height", "cell_size")
_OBS_FIELDS = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    error = _validate(raw)
    if error is not None:
        return {"ok": False, "error": error}
    assert isinstance(raw, dict)
    grid = raw["grid"]
    assert isinstance(grid, dict)
    return _accumulate(
        width=grid["width"],
        height=grid["height"],
        cell_size=grid["cell_size"],
        fill_value=raw["fill_value"],
        observations=raw["observations"],
    )


def _validate(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if not all(field in raw for field in _REQUIRED_FIELDS):
        return "missing field"
    grid_error = _grid_error(raw["grid"], raw["fill_value"])
    if grid_error is not None:
        return grid_error
    if not isinstance(raw["observations"], list):
        return "bad observations"
    return None


def _grid_error(grid: object, fill_value: object) -> str | None:
    if not isinstance(grid, dict):
        return "bad grid"
    if not all(field in grid for field in _GRID_FIELDS):
        return "bad grid"
    if not _in_bounds(grid["width"], 1, MAX_DIM):
        return "bad width"
    if not _in_bounds(grid["height"], 1, MAX_DIM):
        return "bad height"
    if not _in_bounds(grid["cell_size"], 1, None):
        return "bad cell size"
    if not isinstance(fill_value, int):
        return "bad fill value"
    return None


def _in_bounds(value: object, low: int, high: int | None) -> bool:
    if not isinstance(value, int):
        return False
    if value < low:
        return False
    if high is not None and value > high:
        return False
    return True


def _accumulate(
    width: int,
    height: int,
    cell_size: int,
    fill_value: int,
    observations: list,
) -> dict:
    sums: dict = {}
    counts: dict = {}
    degraded: dict = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        result = _eval_observation(obs, width, height, cell_size, tolerance)
        if result is None:
            return {"ok": False, "error": "bad observation"}
        fate, key = result
        if fate == "reject":
            rejected += 1
            continue
        if fate == "drop":
            dropped += 1
            continue
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _eval_observation(
    obs: object,
    width: int,
    height: int,
    cell_size: int,
    tolerance: int,
) -> tuple[str, tuple[int, int] | None] | None:
    if not _obs_shape_ok(obs):
        return None
    assert isinstance(obs, dict)
    key = _target_cell(obs, width, height, cell_size, tolerance)
    if obs["quality"] < MIN_QUALITY:
        return ("reject", key)
    if key is None:
        return ("drop", None)
    return ("use", key)


def _obs_shape_ok(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    for field in _OBS_FIELDS:
        if field not in obs or not isinstance(obs[field], int):
            return False
    return 0 <= obs["quality"] <= 100


def _target_cell(
    obs: dict,
    width: int,
    height: int,
    cell_size: int,
    tolerance: int,
) -> tuple[int, int] | None:
    col = _map_coordinate(obs["x"], width, cell_size, tolerance)
    if col is None:
        return None
    row = _map_coordinate(obs["y"], height, cell_size, tolerance)
    if row is None:
        return None
    return (row, col)


def _map_coordinate(coord: int, dim: int, cell_size: int, tolerance: int) -> int | None:
    if coord < 0:
        return None
    index = coord // cell_size
    if index >= dim:
        if coord - dim * cell_size < tolerance:
            return dim - 1
        return None
    return index


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    error = _validate(raw)
    if error is not None:
        return {"ok": False, "error": error}

    grid = raw["grid"]
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    state = _fold(raw["observations"], width, height, cell_size)
    counts = state["counts"]
    filled = sum(1 for c in counts if c)
    total = width * height
    coverage = filled * 100 // total
    return {
        "ok": True,
        "cells": _rows(state["sums"], counts, width, raw["fill_value"]),
        "flags": _flags(counts, state["degraded"], width),
        "dropped": state["dropped"],
        "rejected": state["rejected"],
        "saturated": state["saturated"],
        "coverage": coverage,
        "line": _summary_line(total, filled, state["dropped"], state["rejected"], state["saturated"], coverage),
    }


def _validate(raw: object) -> str | None:
    checks = (
        _check_input,
        _check_grid,
        _check_width,
        _check_height,
        _check_cell,
        _check_fill,
        _check_observation_list,
        _check_observation_values,
    )
    for check in checks:
        error = check(raw)
        if error is not None:
            return error
    return None


def _check_input(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return "missing field"
    return None


def _check_grid(raw: object) -> str | None:
    grid = raw["grid"] if isinstance(raw, dict) else None
    if not isinstance(grid, dict):
        return "bad grid"
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return "bad grid"
    return None


def _check_width(raw: object) -> str | None:
    value = raw["grid"].get("width") if isinstance(raw, dict) and isinstance(raw.get("grid"), dict) else None
    if not isinstance(value, int) or value < 1 or value > MAX_DIM:
        return "bad width"
    return None


def _check_height(raw: object) -> str | None:
    value = raw["grid"].get("height") if isinstance(raw, dict) and isinstance(raw.get("grid"), dict) else None
    if not isinstance(value, int) or value < 1 or value > MAX_DIM:
        return "bad height"
    return None


def _check_cell(raw: object) -> str | None:
    value = raw["grid"].get("cell_size") if isinstance(raw, dict) and isinstance(raw.get("grid"), dict) else None
    if not isinstance(value, int) or value < 1:
        return "bad cell size"
    return None


def _check_fill(raw: object) -> str | None:
    value = raw.get("fill_value") if isinstance(raw, dict) else None
    if not isinstance(value, int):
        return "bad fill value"
    return None


def _check_observation_list(raw: object) -> str | None:
    value = raw.get("observations") if isinstance(raw, dict) else None
    if not isinstance(value, list):
        return "bad observations"
    return None


def _check_observation_values(raw: object) -> str | None:
    value = raw.get("observations") if isinstance(raw, dict) else None
    if isinstance(value, list) and any(not _is_observation(obs) for obs in value):
        return "bad observation"
    return None


def _is_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    if not isinstance(obs.get("quality"), int) or not 0 <= obs["quality"] <= 100:
        return False
    return (
        isinstance(obs.get("x"), int)
        and isinstance(obs.get("y"), int)
        and isinstance(obs.get("value"), int)
    )


def _fold(observations: list, width: int, height: int, cell_size: int) -> dict:
    size = width * height
    sums = [0] * size
    counts = [0] * size
    degraded = [False] * size
    dropped = 0
    rejected = 0
    saturated = 0
    for obs in observations:
        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue
        index = _target(obs, width, height, cell_size)
        if index is None:
            dropped += 1
        elif counts[index] >= SATURATION_LIMIT:
            saturated += 1
        else:
            sums[index] += obs["value"]
            counts[index] += 1
            if obs["quality"] < GOOD_QUALITY:
                degraded[index] = True
    return {
        "sums": sums,
        "counts": counts,
        "degraded": degraded,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
    }


def _target(obs: dict, width: int, height: int, cell_size: int) -> int | None:
    col = _bin(obs["x"], cell_size, width)
    row = _bin(obs["y"], cell_size, height)
    if col is None or row is None:
        return None
    return row * width + col


def _bin(coord: int, cell_size: int, limit: int) -> int | None:
    if coord < 0:
        return None
    index = coord // cell_size
    if index < limit:
        return index
    if coord - limit * cell_size >= cell_size // 2:
        return None
    return limit - 1


def _rows(sums: list, counts: list, width: int, fill_value: int) -> list:
    return [
        [sums[i] // counts[i] if counts[i] else fill_value for i in range(start, start + width)]
        for start in range(0, len(sums), width)
    ]


def _flags(counts: list, degraded: list, width: int) -> list:
    return [
        [
            "empty" if not counts[i] else ("degraded" if degraded[i] else "good")
            for i in range(start, start + width)
        ]
        for start in range(0, len(counts), width)
    ]


def _summary_line(total: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        f"cells={total}"
        f";filled={filled}"
        f";dropped={dropped}"
        f";rejected={rejected}"
        f";saturated={saturated}"
        f";coverage={coverage}"
    )

from __future__ import annotations

from collections import defaultdict

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

CellKey = tuple[int, int]
ErrorResult = tuple[None, None, str]
PayloadResult = tuple[dict, dict, None]


def accumulate_grid(raw: object) -> dict:
    grid, payload, error = _validate_payload(raw)
    if error is not None:
        return {"ok": False, "error": error}

    stats = _fold_observations(grid, payload["observations"])
    if "error" in stats:
        return {"ok": False, "error": stats["error"]}

    width = grid["width"]
    height = grid["height"]
    counts = stats["counts"]
    total_cells = width * height
    coverage = len(counts) * 100 // total_cells
    cells = _averaged_rows(stats["sums"], counts, width, height, payload["fill_value"])
    flags = _flag_rows(counts, stats["degraded"], width, height)
    line = _summary_line(total_cells, len(counts), stats["dropped"], stats["rejected"],
                         stats["saturated"], coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": stats["dropped"],
        "rejected": stats["rejected"],
        "saturated": stats["saturated"],
        "coverage": coverage,
        "line": line,
    }


def _validate_payload(raw: object) -> PayloadResult | ErrorResult:
    if not isinstance(raw, dict):
        return None, None, "malformed input"
    for field in ("grid", "observations", "fill_value"):
        if field not in raw:
            return None, None, "missing field"

    grid = raw["grid"]
    if not isinstance(grid, dict) or not {"width", "height", "cell_size"} <= set(grid):
        return None, None, "bad grid"
    if not isinstance(grid["width"], int) or not 1 <= grid["width"] <= MAX_DIM:
        return None, None, "bad width"
    if not isinstance(grid["height"], int) or not 1 <= grid["height"] <= MAX_DIM:
        return None, None, "bad height"
    if not isinstance(grid["cell_size"], int) or grid["cell_size"] < 1:
        return None, None, "bad cell size"
    if not isinstance(raw["fill_value"], int):
        return None, None, "bad fill value"
    if not isinstance(raw["observations"], list):
        return None, None, "bad observations"

    return grid, raw, None


def _fold_observations(grid: dict, observations: list) -> dict:
    tolerance = grid["cell_size"] // 2
    sums: dict[CellKey, int] = defaultdict(int)
    counts: dict[CellKey, int] = defaultdict(int)
    degraded: set[CellKey] = set()
    dropped = 0
    rejected = 0
    saturated = 0

    for obs in observations:
        err = _observe(grid, tolerance, obs, sums, counts, degraded)
        if err == "drop":
            dropped += 1
        elif err == "reject":
            rejected += 1
        elif err == "saturate":
            saturated += 1
        elif err != "ok":
            return {"error": err}

    return {
        "sums": sums,
        "counts": counts,
        "degraded": degraded,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
    }


def _observe(
    grid: dict,
    tolerance: int,
    obs: object,
    sums: dict[CellKey, int],
    counts: dict[CellKey, int],
    degraded: set[CellKey],
) -> str:
    if not _valid_observation(obs):
        return "bad observation"
    quality = obs["quality"]
    if quality < MIN_QUALITY:
        return "reject"

    col, in_bounds = _project(obs["x"], grid["cell_size"], grid["width"], tolerance)
    if not in_bounds:
        return "drop"
    row, in_bounds = _project(obs["y"], grid["cell_size"], grid["height"], tolerance)
    if not in_bounds:
        return "drop"

    key = (row, col)
    if counts[key] >= SATURATION_LIMIT:
        return "saturate"
    sums[key] += obs["value"]
    counts[key] += 1
    if quality < GOOD_QUALITY:
        degraded.add(key)
    return "ok"


def _valid_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    for field in ("x", "y", "value", "quality"):
        if not isinstance(obs.get(field), int):
            return False
    return 0 <= obs["quality"] <= 100


def _project(coord: int, cell_size: int, dim: int, tolerance: int) -> tuple[int, bool]:
    if coord < 0:
        return 0, False
    index = coord // cell_size
    if index >= dim:
        if coord - dim * cell_size < tolerance:
            index = dim - 1
        else:
            return 0, False
    return index, True


def _averaged_rows(
    sums: dict[CellKey, int],
    counts: dict[CellKey, int],
    width: int,
    height: int,
    fill_value: int,
) -> list[list[int]]:
    return [
        [sums[(row, col)] // counts[(row, col)]
         if (row, col) in counts else fill_value
         for col in range(width)]
        for row in range(height)
    ]


def _flag_rows(
    counts: dict[CellKey, int],
    degraded: set[CellKey],
    width: int,
    height: int,
) -> list[list[str]]:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    return (
        f"cells={total_cells};filled={filled};dropped={dropped};"
        f"rejected={rejected};saturated={saturated};coverage={coverage}"
    )

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

_OBS_FIELDS = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    valid, payload = _validate_input(raw)
    if not valid:
        return payload

    grid = payload["grid"]
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    fill_value = payload["fill_value"]

    sums, counts, degraded, dropped, rejected, saturated = _accumulate_observations(
        payload["observations"], width, height, cell_size
    )

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": _summary_line(
            width * height,
            len(counts),
            dropped,
            rejected,
            saturated,
            coverage,
        ),
    }


def _validate_input(raw: object) -> tuple[bool, dict]:
    error = _input_shape_error(raw)
    if error is None:
        error = _grid_shape_error(raw["grid"])
    if error is not None:
        return False, {"ok": False, "error": error}

    for obs in raw["observations"]:
        if not _is_valid_observation(obs):
            return False, {"ok": False, "error": "bad observation"}

    return True, {
        "grid": raw["grid"],
        "fill_value": raw["fill_value"],
        "observations": raw["observations"],
    }


def _validate_input(raw: object) -> tuple[bool, dict]:
    error = _raw_shape_error(raw)
    if error is None:
        error = _grid_shape_error(raw["grid"])
    if error is None:
        error = _scalar_shape_error(raw)
    if error is not None:
        return False, {"ok": False, "error": error}

    for obs in raw["observations"]:
        if not _is_valid_observation(obs):
            return False, {"ok": False, "error": "bad observation"}

    return True, {
        "grid": raw["grid"],
        "fill_value": raw["fill_value"],
        "observations": raw["observations"],
    }


def _raw_shape_error(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return "missing field"
    if not isinstance(raw["observations"], list):
        return "bad observations"
    return None


def _scalar_shape_error(raw: dict) -> str | None:
    if not isinstance(raw["fill_value"], int):
        return "bad fill value"
    return None


def _grid_shape_error(grid: object) -> str | None:
    if not isinstance(grid, dict):
        return "bad grid"
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return "bad grid"
    return _field_error(grid, "width", "bad width", 1, MAX_DIM) or _field_error(
        grid, "height", "bad height", 1, MAX_DIM
    ) or _field_error(grid, "cell_size", "bad cell size", 1, None)


def _field_error(grid: dict, name: str, message: str, minimum: int, maximum: int | None) -> str | None:
    value = grid[name]
    if not isinstance(value, int) or value < minimum:
        return message
    if maximum is not None and value > maximum:
        return message
    return None


def _is_valid_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    for field in _OBS_FIELDS:
        if field not in obs or not isinstance(obs[field], int):
            return False
    return 0 <= obs["quality"] <= 100


def _accumulate_observations(
    observations: list, width: int, height: int, cell_size: int
) -> tuple[dict, dict, dict, int, int, int]:
    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        quality = obs["quality"]
        if quality < MIN_QUALITY:
            rejected = rejected + 1
            continue

        key = _project(obs["x"], obs["y"], width, height, cell_size, tolerance)
        if key is None:
            dropped = dropped + 1
            continue

        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded[key] = True

    return sums, counts, degraded, dropped, rejected, saturated


def _project(
    x: int, y: int, width: int, height: int, cell_size: int, tolerance: int
) -> tuple[int, int] | None:
    if x < 0:
        return None
    col = x // cell_size
    if col >= width:
        if x - width * cell_size < tolerance:
            col = width - 1
        else:
            return None

    if y < 0:
        return None
    row = y // cell_size
    if row >= height:
        if y - height * cell_size < tolerance:
            row = height - 1
        else:
            return None

    return (row, col)


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            cells.append(sums[key] // counts[key] if key in counts else fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
