    try:
        width, height, cell_size, fill_value, observations = _parse_input(raw)
    except _ValidationError as exc:
        return {"ok": False, "error": exc.reason}

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue
        cell = _cell_key(obs, width, height, cell_size, tolerance)
        if cell is None:
            dropped = dropped + 1
            continue
        if counts.get(cell, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[cell] = sums.get(cell, 0) + obs["value"]
        counts[cell] = counts.get(cell, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[cell] = True

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
