def _cell_key(obs: dict, width: int, height: int, cell_size: int, tolerance: int) -> tuple[int, int] | None:
    col = _column_index(obs["x"], width, cell_size, tolerance)
    if col is None:
        return None
    row = _column_index(obs["y"], height, cell_size, tolerance)
    if row is None:
        return None
    return (row, col)


def _column_index(value: int, dim: int, cell_size: int, tolerance: int) -> int | None:
    if value < 0:
        return None
    index = value // cell_size
    if index < dim:
        return index
    if value - dim * cell_size < tolerance:
        return dim - 1
    return None


def _parse_input(raw: object) -> tuple[int, int, int, int, list]:
    if not isinstance(raw, dict):
        raise _ValidationError("malformed input")
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        raise _ValidationError("missing field")

    grid = raw["grid"]
    if not isinstance(grid, dict):
        raise _ValidationError("bad grid")
    for field in ("width", "height", "cell_size"):
        if field not in grid:
            raise _ValidationError("bad grid")

    width = _require_int(grid["width"], "bad width")
    height = _require_int(grid["height"], "bad height")
    cell_size = _require_int(grid["cell_size"], "bad cell size")
    if not (1 <= width <= MAX_DIM):
        raise _ValidationError("bad width")
    if not (1 <= height <= MAX_DIM):
        raise _ValidationError("bad height")
    if cell_size < 1:
        raise _ValidationError("bad cell size")
    fill_value = _require_int(raw["fill_value"], "bad fill value")

    observations = raw["observations"]
    if not isinstance(observations, list):
        raise _ValidationError("bad observations")

    parsed = []
    for obs in observations:
