def _place(obs: dict, width: int, height: int, cell_size: int, sums: dict, counts: dict, degraded: dict) -> str:
    if obs["quality"] < MIN_QUALITY:
        return "rejected"
    col = _map_index(obs["x"], cell_size, width)
    if col is None:
        return "dropped"
    row = _map_index(obs["y"], cell_size, height)
    if row is None:
