from __future__ import annotations

from collections.abc import Callable

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

VALID_TIERS = frozenset(TIER_FEES)
VALID_METHODS = ("card", "transfer")


def _valid_tier(tier: object) -> bool:
    return tier in VALID_TIERS


def _valid_amount(amount: object) -> bool:
    return isinstance(amount, int) and amount > 0


def _valid_method(method: object) -> bool:
    return method in VALID_METHODS


def _receipt(method: str, member_id: str, status: str, fee: int) -> str:
    return f"{method}:{member_id}:{status}:{fee}"


def _fail(error: str) -> dict:
    return {"ok": False, "error": error}


def _success(member: dict, payment: dict, status: str, fee: int) -> dict:
    return {
        "ok": True,
        "status": status,
        "fee": fee,
        "receipt": _receipt(payment["method"], member["id"], status, fee),
    }


def _handle_active(member: dict, payment: dict) -> dict:
    if not _valid_tier(member["tier"]):
        return _fail("unknown tier")
    if not _valid_amount(payment["amount"]):
        return _fail("bad amount")
    if not _valid_method(payment["method"]):
        return _fail("unsupported method")
    fee = TIER_FEES[member["tier"]]
    if payment["amount"] < fee:
        return _fail("insufficient payment")
    return _success(member, payment, "renewed", fee)


def _handle_lapsed(member: dict, payment: dict) -> dict:
    if not _valid_tier(member["tier"]):
        return _fail("unknown tier")
    expired_days = member.get("expired_days")
    if (
        not isinstance(expired_days, int)
        or expired_days < 0
    ):
        return _fail("bad expiry")
    if not _valid_amount(payment["amount"]):
        return _fail("bad amount")
    if not _valid_method(payment["method"]):
        return _fail("unsupported method")
    if expired_days <= GRACE_DAYS:
        fee = TIER_FEES[member["tier"]] + LATE_FEE
        status = "renewed"
    else:
        fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
        status = "reinstated"
    if payment["amount"] < fee:
        return _fail("insufficient payment")
    return _success(member, payment, status, fee)


def _handle_suspended(member: dict, payment: dict) -> dict:
    if not _valid_tier(member["tier"]):
        return _fail("unknown tier")
    strikes = member.get("strikes")
    if not isinstance(strikes, int) or strikes < 0:
        return _fail("bad strikes")
    if strikes >= MAX_STRIKES:
        return _fail("too many strikes")
    if not _valid_amount(payment["amount"]):
        return _fail("bad amount")
    if not _valid_method(payment["method"]):
        return _fail("unsupported method")
    fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
    if payment["amount"] < fee:
        return _fail("insufficient payment")
    return _success(member, payment, "reactivated", fee)


def _handle_banned(member: dict, payment: dict) -> dict:
    return _fail("member banned")


Handler = Callable[[dict, dict], dict]

HANDLERS: dict[str, Handler] = {
    "active": _handle_active,
    "lapsed": _handle_lapsed,
    "suspended": _handle_suspended,
    "banned": _handle_banned,
}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return _fail("malformed input")
    if (
        "id" not in raw_member
        or "status" not in raw_member
        or "tier" not in raw_member
        or "amount" not in raw_payment
        or "method" not in raw_payment
    ):
        return _fail("missing member field")
    if not isinstance(raw_member["id"], str) or len(raw_member["id"]) == 0:
        return _fail("bad member id")

    handler = HANDLERS.get(raw_member["status"])
    if handler is None:
        return _fail("unknown status")
    return handler(raw_member, raw_payment)

