MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

_METHODS = ("card", "transfer")


def _malformed(raw_member: object, raw_payment: object) -> dict | None:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    return None


def _missing_fields(member: dict, payment: dict) -> dict | None:
    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    return None


def _bad_id(member: dict) -> dict | None:
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return {"ok": False, "error": "bad member id"}
    return None


def _banned(member: dict) -> dict | None:
    if member["status"] == "banned":
        return {"ok": False, "error": "member banned"}
    return None


def _bad_tier(member: dict) -> dict | None:
    if member["tier"] not in TIER_FEES:
        return {"ok": False, "error": "unknown tier"}
    return None


def _bad_payment(payment: dict) -> dict | None:
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment["method"] not in _METHODS:
        return {"ok": False, "error": "unsupported method"}
    return None


def _insufficient(payment: dict, fee: int) -> dict | None:
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return None


def _receipt(member: dict, payment: dict, action: str, fee: int) -> str:
    return f"{payment['method']}:{member['id']}:{action}:{fee}"


def _renew_active(member: dict, payment: dict) -> dict:
    if (err := _bad_tier(member)) or (err := _bad_payment(payment)):
        return err
    fee = TIER_FEES[member["tier"]]
    if (err := _insufficient(payment, fee)):
        return err
    return {"ok": True, "status": "renewed", "fee": fee,
            "receipt": _receipt(member, payment, "renewed", fee)}


def _renew_lapsed(member: dict, payment: dict) -> dict:
    if (err := _bad_tier(member)):
        return err
    if "expired_days" not in member or not isinstance(member["expired_days"], int) or member["expired_days"] < 0:
        return {"ok": False, "error": "bad expiry"}
    if (err := _bad_payment(payment)):
        return err
    if member["expired_days"] <= GRACE_DAYS:
        fee = TIER_FEES[member["tier"]] + LATE_FEE
        status = "renewed"
    else:
        fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
        status = "reinstated"
    if (err := _insufficient(payment, fee)):
        return err
    return {"ok": True, "status": status, "fee": fee,
            "receipt": _receipt(member, payment, status, fee)}


def _renew_suspended(member: dict, payment: dict) -> dict:
    if (err := _bad_tier(member)):
        return err
    if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
        return {"ok": False, "error": "bad strikes"}
    if member["strikes"] >= MAX_STRIKES:
        return {"ok": False, "error": "too many strikes"}
    if (err := _bad_payment(payment)):
        return err
    fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
    if (err := _insufficient(payment, fee)):
        return err
    return {"ok": True, "status": "reactivated", "fee": fee,
            "receipt": _receipt(member, payment, "reactivated", fee)}


_RENEWALS: dict[str, Callable[[dict, dict], dict]] = {
    "active": _renew_active,
    "lapsed": _renew_lapsed,
    "suspended": _renew_suspended,
}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if (err := _malformed(raw_member, raw_payment)):
        return err
    member = raw_member
    payment = raw_payment
    if (err := _missing_fields(member, payment)):
        return err
    if (err := _bad_id(member)):
        return err
    if (err := _banned(member)):
        return err

    handler = _RENEWALS.get(member["status"])
    if handler is None:
        return {"ok": False, "error": "unknown status"}
    return handler(member, payment)

