from __future__ import annotations

from typing import Any

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

GRID_FIELDS = ("width", "height", "cell_size")


def accumulate_grid(raw: object) -> dict[str, Any]:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if not all(name in raw for name in ("grid", "observations", "fill_value")):
        return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict) or not all(name in grid for name in GRID_FIELDS):
        return {"ok": False, "error": "bad grid"}

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or not 1 <= width <= MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or not 1 <= height <= MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}

    fill_value = raw["fill_value"]
    if not isinstance(fill_value, int):
        return {"ok": False, "error": "bad fill value"}

    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: dict[tuple[int, int], bool] = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        error, quality = _parse_observation(obs)
        if error is not None:
            return {"ok": False, "error": error}
        if quality < MIN_QUALITY:
            rejected += 1
            continue

        x = obs["x"]
        y = obs["y"]
        if x < 0 or y < 0:
            dropped += 1
            continue

        col = _index(x, cell_size, width, tolerance)
        if col is None:
            dropped += 1
            continue
        row = _index(y, cell_size, height, tolerance)
        if row is None:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded[key] = True

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _index(coord: int, cell_size: int, size: int, tolerance: int) -> int | None:
    index = coord // cell_size
    if index >= size:
        if coord - size * cell_size < tolerance:
            index = size - 1
        else:
            return None
    return index


def _parse_observation(obs: object) -> tuple[str | None, int]:
    if not isinstance(obs, dict):
        return "bad observation", 0
    for name in ("x", "y", "value", "quality"):
        if not isinstance(obs.get(name), int):
            return "bad observation", 0
    quality = obs["quality"]
    if quality < 0 or quality > 100:
        return "bad observation", 0
    return None, quality


def _averaged_rows(
    sums: dict[tuple[int, int], int],
    counts: dict[tuple[int, int], int],
    width: int,
    height: int,
    fill_value: int,
) -> list[list[int]]:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            count = counts.get(key)
            cells.append(sums[key] // count if count else fill_value)
        rows.append(cells)
    return rows


def _flag_rows(
    counts: dict[tuple[int, int], int],
    degraded: dict[tuple[int, int], bool],
    width: int,
    height: int,
) -> list[list[str]]:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict[tuple[int, int], int], width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    return (
        f"cells={total_cells}"
        f";filled={filled}"
        f";dropped={dropped}"
        f";rejected={rejected}"
        f";saturated={saturated}"
        f";coverage={coverage}"
    )

