    "active": _active_plan,
    "lapsed": _lapsed_plan,
    "suspended": _suspended_plan,
}


def _receipt(method: str, member_id: str, status: str, fee: int) -> str:
    return f"{method}:{member_id}:{status}:{fee}"


def _success(status: str, member: dict, payment: dict, fee: int) -> dict:
    return {
        "ok": True,
        "status": status,
        "fee": fee,
        "receipt": _receipt(payment["method"], member["id"], status, fee),
    }


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    invalid = _validate_input(raw_member, raw_payment)
    if invalid is not None:
        return invalid
    member, payment = raw_member, raw_payment

