GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

VALID_STATUSES = ("active", "lapsed", "suspended")


def _bad_fields(member: dict, payment: dict) -> str | None:
    if "id" not in member or "status" not in member or "tier" not in member:
        return "missing member field"
    if "amount" not in payment or "method" not in payment:
        return "missing payment field"
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return "bad member id"
    return None


def _bad_tier(member: dict) -> str | None:
    if member["tier"] not in TIER_FEES:
        return "unknown tier"
    return None


def _bad_expiry(member: dict) -> str | None:
    expired = member.get("expired_days")
    if not isinstance(expired, int) or expired < 0:
        return "bad expiry"
    return None


def _bad_strikes(member: dict) -> str | None:
    strikes = member.get("strikes")
    if not isinstance(strikes, int) or strikes < 0:
        return "bad strikes"
    if strikes >= MAX_STRIKES:
        return "too many strikes"
    return None


def _bad_amount(payment: dict) -> str | None:
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    return None


def _bad_method(payment: dict) -> str | None:
    if payment["method"] not in ("card", "transfer"):
        return "unsupported method"
    return None


def _status_specific_checks(status: str) -> tuple:
    if status == "lapsed":
        return (_bad_tier, _bad_expiry)
    if status == "suspended":
        return (_bad_tier, _bad_strikes)
    return (_bad_tier,)


def validate_input(member: dict, payment: dict) -> dict | None:
    error = _bad_fields(member, payment)
    if error is not None:
        return {"ok": False, "error": error}

    if member["status"] == "banned":
        return {"ok": False, "error": "member banned"}
    if member["status"] not in VALID_STATUSES:
        return {"ok": False, "error": "unknown status"}

    for check in _status_specific_checks(member["status"]):
        error = check(member)
        if error is not None:
            return {"ok": False, "error": error}

    for check in (_bad_amount, _bad_method):
        error = check(payment)
        if error is not None:
            return {"ok": False, "error": error}
    return None


def _active_plan(member: dict) -> dict:
    return {"status": "renewed", "fee": TIER_FEES[member["tier"]]}


def _lapsed_plan(member: dict) -> dict:
    base = TIER_FEES[member["tier"]]
    if member["expired_days"] <= GRACE_DAYS:
        return {"status": "renewed", "fee": base + LATE_FEE}
    return {"status": "reinstated", "fee": base + REINSTATE_SURCHARGE}


def _suspended_plan(member: dict) -> dict:
    base = TIER_FEES[member["tier"]]
    return {"status": "reactivated", "fee": base + base // 2}


PLANS = {
    "active": _active_plan,
    "lapsed": _lapsed_plan,
    "suspended": _suspended_plan,
}


def confirm_payment(payment: dict, fee: int) -> bool:
    return payment["amount"] >= fee


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}

    member = raw_member
    payment = raw_payment

    invalid = validate_input(member, payment)
    if invalid is not None:
        return invalid

    plan = PLANS[member["status"]](member)
    if not confirm_payment(payment, plan["fee"]):
        return {"ok": False, "error": "insufficient payment"}

    return {
        "ok": True,
        "status": plan["status"],
        "fee": plan["fee"],
        "receipt": f"{payment['method']}:{member['id']}:{plan['status']}:{plan['fee']}",
    }

