    base = TIER_FEES[member["tier"]]
    fee = base + base // 2
    if payment["amount"] < fee:
        return _refuse("insufficient payment")
    return _success(member, payment, "reactivated", fee)


def _member_banned(member: dict, payment: dict) -> dict:
    return _refuse("member banned")


_HANDLERS = {
