export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Req = Record<string, unknown>;

interface Quotation {
  name: string;
  base: number;
  peak: number;
  maxNights: number;
  maxGuests: number;
  minStay: number;
  minStayError?: string;
  fixedFee: (req: Req) => number;
}

const QUOTATIONS: Record<string, Quotation> = {
  standard: {
    name: "standard",
    base: 80,
    peak: 30,
    maxNights: 14,
    maxGuests: 2,
    minStay: 1,
    fixedFee: () => 0,
  },
  suite: {
    name: "suite",
    base: 150,
    peak: 60,
    maxNights: 21,
    maxGuests: 4,
    minStay: 1,
    fixedFee: (req) => (req.guests as number) > 2 ? 25 : 0,
  },
  villa: {
    name: "villa",
    base: 300,
    peak: 120,
    maxNights: 28,
    maxGuests: 8,
    minStay: 3,
    minStayError: "villa minimum stay",
    fixedFee: () => 500,
  },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Req;
  if (!isIntInRange(req.loyaltyYears, 0, Infinity)) {
    return { ok: false, error: "bad loyalty" };
  }
  const q = QUOTATIONS[req.category as string];
  if (!q) {
    return { ok: false, error: "unknown category" };
  }
  return quote(req, q, req.loyaltyYears as number, req.season, req.coupon === "VIP");
}

function isIntInRange(value: unknown, min: number, max: number): boolean {
  return Number.isInteger(value) && (value as number) >= min && (value as number) <= max;
}

function quote(req: Req, q: Quotation, loyalty: number, season: unknown, vip: boolean): QuoteResult {
  if (constraintError(req, q) !== null) {
    return { ok: false, error: constraintError(req, q)! };
  }
  const nights = req.nights as number;
  const total = price(req, q, loyalty, season, vip);
  const policy = vip || loyalty >= 3 ? "flex" : "strict";
  return {
    ok: true,
    total,
    policy,
    line: `${q.name}:${nights}n:${total}:${policy}`,
  };
}

function constraintError(req: Req, q: Quotation): string | null {
  if (!isIntInRange(req.nights, 1, q.maxNights)) {
    return "bad nights";
  }
  if ((req.nights as number) < q.minStay) {
    return q.minStayError ?? "bad nights";
  }
  if (!isIntInRange(req.guests, 1, q.maxGuests)) {
    return "bad guests";
  }
  if (req.season !== "low" && req.season !== "high") {
    return "bad season";
  }
  return null;
}

function price(req: Req, q: Quotation, loyalty: number, season: unknown, vip: boolean): number {
  const nights = req.nights as number;
  let total = q.base * nights + (season === "high" ? q.peak * nights : 0);
  if (vip || loyalty >= 3) {
    total -= Math.floor(total / 10);
  }
  return total + q.fixedFee(req);
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  maxNights: number;
  minNights: number;
  minGuests: number;
  maxGuests: number;
  minStay?: number;
  baseRate: number;
  highRate: number;
  fixedExtra?: number;
  guestSurcharge?: number;
  surchargeFrom?: number;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: { maxNights: 14, minNights: 1, minGuests: 1, maxGuests: 2, baseRate: 80, highRate: 30 },
  suite: { maxNights: 21, minNights: 1, minGuests: 1, maxGuests: 4, baseRate: 150, highRate: 60, guestSurcharge: 25, surchargeFrom: 3 },
  villa: { maxNights: 28, minNights: 1, minGuests: 1, maxGuests: 8, baseRate: 300, highRate: 120, minStay: 3, fixedExtra: 500 },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  const category = req.category as string;

  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  if (!(category in CATEGORIES)) {
    return { ok: false, error: "unknown category" };
  }

  const config = CATEGORIES[category];
  const error = validateRequest(config, req.nights, req.guests, req.season, category);
  if (error) {
    return { ok: false, error };
  }

  const preferred = isPreferred(req.loyaltyYears as number, req.coupon);
  const total = computeTotal(config, req.nights as number, req.guests as number, req.season, preferred);
  const policy = preferred ? "flex" : "strict";
  const line = category + ":" + String(req.nights) + "n:" + String(total) + ":" + policy;
  return { ok: true, total, policy, line };
}

function isPreferred(loyaltyYears: number, coupon: unknown): boolean {
  return loyaltyYears > 2 || coupon === "VIP";
}

function validateRequest(
  config: CategoryConfig,
  nights: unknown,
  guests: unknown,
  season: unknown,
  category: string,
): string | null {
  const badNights = checkNights(config, nights);
  if (badNights) {
    return badNights;
  }
  if (config.minStay !== undefined && (nights as number) < config.minStay) {
    return category + " minimum stay";
  }
  const badGuests = checkGuests(config, guests);
  if (badGuests) {
    return badGuests;
  }
  const badSeason = checkSeason(season);
  if (badSeason) {
    return badSeason;
  }
  return null;
}

function checkNights(config: CategoryConfig, nights: unknown): string | null {
  if (!Number.isInteger(nights) || (nights as number) < config.minNights || (nights as number) > config.maxNights) {
    return "bad nights";
  }
  return null;
}

function checkGuests(config: CategoryConfig, guests: unknown): string | null {
  if (!Number.isInteger(guests) || (guests as number) < config.minGuests || (guests as number) > config.maxGuests) {
    return "bad guests";
  }
  return null;
}

function checkSeason(season: unknown): string | null {
  return season === "low" || season === "high" ? null : "bad season";
}

function computeTotal(
  config: CategoryConfig,
  nights: number,
  guests: number,
  season: unknown,
  preferred: boolean,
): number {
  let total = config.baseRate * nights;
  if (season === "high") {
    total += config.highRate * nights;
  }
  if (preferred) {
    total -= Math.floor(total / 10);
  }
  if (config.fixedExtra !== undefined) {
    total += config.fixedExtra;
  }
  if (config.guestSurcharge !== undefined && guests >= (config.surchargeFrom ?? 0)) {
    total += config.guestSurcharge;
  }
  return total;
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  name: "standard" | "suite" | "villa";
  minNights: number;
  maxNights: number;
  minGuests: number;
  maxGuests: number;
  baseRate: number;
  highPremium: number;
  minStay?: number;
  serviceFee?: number;
  perExtraGuest?: number;
  discount: (loyaltyYears: number, coupon: string | undefined) => boolean;
  flexPolicy: (loyaltyYears: number, coupon: string | undefined) => boolean;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: {
    name: "standard",
