    flexPolicy: (y, c) => c === "VIP" || y >= 3,
  },
};

function isBadNights(req: Record<string, unknown>, cfg: CategoryConfig): boolean {
  const nights = req.nights as number;
  return !Number.isInteger(nights) || nights < cfg.minNights || nights > cfg.maxNights;
}

function isBadGuests(req: Record<string, unknown>, cfg: CategoryConfig): boolean {
  const guests = req.guests as number;
  return !Number.isInteger(guests) || guests < cfg.minGuests || guests > cfg.maxGuests;
}

function validate(req: Record<string, unknown>, cfg: CategoryConfig): string | undefined {
  if (isBadNights(req, cfg)) return "bad nights";
  if (cfg.minStay !== undefined && (req.nights as number) < cfg.minStay) return "villa minimum stay";
  if (isBadGuests(req, cfg)) return "bad guests";
  if (req.season !== "low" && req.season !== "high") return "bad season";
}

interface PricedQuote {
  total: number;
  policy: string;
  line: string;
}

function price(req: Record<string, unknown>, cfg: CategoryConfig): PricedQuote {
  const loyaltyYears = req.loyaltyYears as number;
  const nights = req.nights as number;
  const guests = req.guests as number;
  const coupon = typeof req.coupon === "string" ? req.coupon : undefined;

  let total = cfg.baseRate * nights;
  if (req.season === "high") total += cfg.highPremium * nights;
  if (cfg.discount(loyaltyYears, coupon)) total -= Math.floor(total / 10);
  if (cfg.perExtraGuest !== undefined && guests > 2) total += cfg.perExtraGuest;
  if (cfg.serviceFee !== undefined) total += cfg.serviceFee;

  const policy = cfg.flexPolicy(loyaltyYears, coupon) ? "flex" : "strict";
  return { total, policy, line: `${cfg.name}:${nights}n:${total}:${policy}` };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  const cfg = CATEGORIES[req.category as string];
  if (!cfg) return { ok: false, error: "unknown category" };

  const error = validate(req, cfg);
  if (error) return { ok: false, error };
  return { ok: true, ...price(req, cfg) };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategorySpec {
  maxNights: number;
  minNights?: number;
  maxGuests: number;
  baseRate: number;
  highSurcharge: number;
  flatFee: number;
  extraGuestThreshold: number;
  perExtraGuest: number;
}

export const CATEGORY_SPECS: Record<string, CategorySpec | undefined> = {
  standard: {
    maxNights: 14,
    maxGuests: 2,
    baseRate: 80,
    highSurcharge: 30,
    flatFee: 0,
    extraGuestThreshold: Infinity,
    perExtraGuest: 0,
  },
  suite: {
    maxNights: 21,
    maxGuests: 4,
    baseRate: 150,
    highSurcharge: 60,
    flatFee: 0,
    extraGuestThreshold: 2,
    perExtraGuest: 25,
  },
  villa: {
    maxNights: 28,
    minNights: 3,
    maxGuests: 8,
    baseRate: 300,
    highSurcharge: 120,
    flatFee: 500,
    extraGuestThreshold: Infinity,
    perExtraGuest: 0,
  },
};

type ValidationRule = {
  name: string;
  violates: (req: Record<string, unknown>, spec: CategorySpec) => boolean;
};

const VALIDATION_RULES: ValidationRule[] = [
  {
    name: "bad nights",
    violates: (req, spec) => {
      const nights = req.nights as number;
      return (
        !Number.isInteger(req.nights) || nights < 1 || nights > spec.maxNights
      );
    },
  },
  {
    name: "villa minimum stay",
    violates: (req, spec) =>
      spec.minNights !== undefined && (req.nights as number) < spec.minNights,
  },
  {
    name: "bad guests",
    violates: (req, spec) => {
      const guests = req.guests as number;
      return (
        !Number.isInteger(req.guests) || guests < 1 || guests > spec.maxGuests
      );
    },
  },
  {
    name: "bad season",
    violates: (req) => req.season !== "low" && req.season !== "high",
  },
];

function validationError(
  req: Record<string, unknown>,
  spec: CategorySpec,
): string | null {
  for (const rule of VALIDATION_RULES) {
    if (rule.violates(req, spec)) {
      return rule.name;
    }
  }
  return null;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const category = req.category as string;
  const spec = CATEGORY_SPECS[category];
  if (spec === undefined) {
    return { ok: false, error: "unknown category" };
  }

  const error = validationError(req, spec);
  if (error) {
    return { ok: false, error };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;
  const loyaltyYears = req.loyaltyYears as number;

  const hasPerk = req.coupon === "VIP" || loyaltyYears >= 3;

  let total = nights * spec.baseRate;
  if (req.season === "high") {
    total += nights * spec.highSurcharge;
  }
  if (hasPerk) {
    total -= Math.floor(total / 10);
  }
  if (guests > spec.extraGuestThreshold) {
    total += spec.perExtraGuest;
  }
  total += spec.flatFee;

  const policy = hasPerk ? "flex" : "strict";
  const line = `${category}:${nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Category = "standard" | "suite" | "villa";
type Season = "low" | "high";

interface CategoryConfig {
  label: string;
  baseRate: number;
  highSurcharge: number;
  minNights: number;
  maxNights: number;
  minGuests: number;
  maxGuests: number;
  guestSurcharge: number;
  cleaningFee: number;
  minStayNights: number;
}

const CATEGORIES: Record<Category, CategoryConfig> = {
  standard: { label: "standard", baseRate: 80, highSurcharge: 30, minNights: 1, maxNights: 14, minGuests: 1, maxGuests: 2, guestSurcharge: 0, cleaningFee: 0, minStayNights: 0 },
  suite: { label: "suite", baseRate: 150, highSurcharge: 60, minNights: 1, maxNights: 21, minGuests: 1, maxGuests: 4, guestSurcharge: 25, cleaningFee: 0, minStayNights: 0 },
  villa: { label: "villa", baseRate: 300, highSurcharge: 120, minNights: 1, maxNights: 28, minGuests: 1, maxGuests: 8, guestSurcharge: 0, cleaningFee: 500, minStayNights: 3 },
};

function isInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value);
}

function inRange(value: number, min: number, max: number): boolean {
  return value >= min && value <= max;
}

function isSeason(value: unknown): value is Season {
  return value === "low" || value === "high";
}

function isCategory(value: unknown): value is Category {
  return value === "standard" || value === "suite" || value === "villa";
}

interface ValidBooking {
  category: Category;
  nights: number;
  guests: number;
  season: Season;
  isVip: boolean;
  isLoyal: boolean;
}

function validateBooking(
  raw: Record<string, unknown>,
  config: CategoryConfig,
): { ok: true; booking: ValidBooking } | { ok: false; error: string } {
  const nights = raw.nights;
  if (!isInteger(nights) || !inRange(nights, config.minNights, config.maxNights)) {
    return { ok: false, error: "bad nights" };
  }
  if (nights < config.minStayNights) {
    return { ok: false, error: "villa minimum stay" };
  }

  const guests = raw.guests;
  if (!isInteger(guests) || !inRange(guests, config.minGuests, config.maxGuests)) {
    return { ok: false, error: "bad guests" };
  }

  const season = raw.season;
  if (!isSeason(season)) {
    return { ok: false, error: "bad season" };
  }

  const loyaltyYears = raw.loyaltyYears as number;
  return {
    ok: true,
    booking: {
      category: raw.category as Category,
      nights,
      guests,
      season,
      isVip: raw.coupon === "VIP",
      isLoyal: loyaltyYears >= 3,
    },
  };
}

function computeQuote(
  config: CategoryConfig,
  b: ValidBooking,
): { total: number; policy: string } {
  let total = config.baseRate * b.nights;
  if (b.season === "high") {
    total = total + config.highSurcharge * b.nights;
  }
  const discounted = b.isVip || b.isLoyal;
  if (discounted) {
    total = total - Math.floor(total / 10);
  }
  if (b.guests > 2) {
    total = total + config.guestSurcharge;
  }
  total = total + config.cleaningFee;
  return { total, policy: discounted ? "flex" : "strict" };
}

function buildResult(config: CategoryConfig, b: ValidBooking, total: number, policy: string): QuoteResult {
  const line = `${config.label}:${b.nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
