  perExtraGuestFee?: number;
  guestExcessThreshold?: number;
}

interface ParsedRequest {
  category: string;
  nights: number;
  guests: number;
  loyaltyYears: number;
  coupon: unknown;
  season: unknown;
  rule: CategoryRule;
}

const CATEGORIES: Record<string, CategoryRule> = {
  standard: {
    minNights: 1,
    maxNights: 14,
    minGuests: 1,
    maxGuests: 2,
    baseRate: 80,
    highRate: 30,
    discountThreshold: 3,
