    highRate: 60,
    discountThreshold: 3,
    flexThreshold: 3,
    guestExcessThreshold: 2,
    perExtraGuestFee: 25,
  },
  villa: {
    minNights: 1,
    maxNights: 28,
    minGuests: 1,
    maxGuests: 8,
    minStayNights: 3,
    baseRate: 300,
    highRate: 120,
    discountThreshold: 3,
    flexThreshold: 3,
    flatFee: 500,
  },
};

function parseRequest(raw: unknown): QuoteResult | ParsedRequest {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const category = req.category as string;
  const nights = req.nights as number;
  const guests = req.guests as number;
  const rule = CATEGORIES[category];
  if (!rule) {
    return { ok: false, error: "unknown category" };
  }

  if (
    !Number.isInteger(req.nights) ||
    nights < rule.minNights ||
    nights > rule.maxNights
  ) {
    return { ok: false, error: "bad nights" };
  }
  if (rule.minStayNights !== undefined && nights < rule.minStayNights) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (
    !Number.isInteger(req.guests) ||
    guests < rule.minGuests ||
    guests > rule.maxGuests
  ) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  return {
    category,
    nights,
    guests,
    loyaltyYears: req.loyaltyYears as number,
    coupon: req.coupon,
    season: req.season,
    rule,
