}

function computeTotal(
  rule: CategoryRule,
  season: unknown,
  nights: number,
  guests: number,
  loyaltyYears: number,
  coupon: unknown,
): number {
  let total = rule.baseRate * nights;
  if (season === "high") {
    total = total + rule.highRate * nights;
  }
  if (coupon === "VIP" || loyaltyYears >= rule.discountThreshold) {
    total = total - Math.floor(total / 10);
  }
  if (
    rule.perExtraGuestFee !== undefined &&
    guests > rule.guestExcessThreshold!
  ) {
    total = total + rule.perExtraGuestFee;
  }
  if (rule.flatFee !== undefined) {
    total = total + rule.flatFee;
  }
  return total;
}

function derivePolicy(
  rule: CategoryRule,
  loyaltyYears: number,
  coupon: unknown,
): string {
  return coupon === "VIP" || loyaltyYears >= rule.flexThreshold
    ? "flex"
    : "strict";
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseRequest(raw);
