export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  code: string;
  maxNights: number;
  maxGuests: number;
  minNights?: number;
  baseRate: number;
  highSeasonSurcharge: number;
  fixedFee?: number;
  guestSurcharge?: { perGuestAbove: number; amount: number };
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: {
    code: "standard",
    maxNights: 14,
    maxGuests: 2,
    baseRate: 80,
    highSeasonSurcharge: 30,
  },
  suite: {
    code: "suite",
    maxNights: 21,
    maxGuests: 4,
    baseRate: 150,
    highSeasonSurcharge: 60,
    guestSurcharge: { perGuestAbove: 2, amount: 25 },
  },
  villa: {
    code: "villa",
    maxNights: 28,
    maxGuests: 8,
    minNights: 3,
    baseRate: 300,
    highSeasonSurcharge: 120,
    fixedFee: 500,
  },
};

interface Booking {
  config: CategoryConfig;
  loyaltyYears: number;
  coupon: unknown;
  nights: number;
  guests: number;
  season: string;
}

function hasLoyaltyBenefit(loyaltyYears: number, coupon: unknown): boolean {
  return loyaltyYears >= 3 || coupon === "VIP";
}

function computeQuote(b: Booking): QuoteResult {
  const benefit = hasLoyaltyBenefit(b.loyaltyYears, b.coupon);
  let total = b.config.baseRate * b.nights;
  if (b.season === "high") {
    total += b.config.highSeasonSurcharge * b.nights;
  }
  if (benefit) {
    total -= Math.floor(total / 10);
  }
  if (b.config.guestSurcharge && b.guests > b.config.guestSurcharge.perGuestAbove) {
    total += b.config.guestSurcharge.amount;
  }
  if (b.config.fixedFee !== undefined) {
    total += b.config.fixedFee;
  }

  const policy = benefit ? "flex" : "strict";
  const line = `${b.config.code}:${b.nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const config = CATEGORIES[req.category as string];
  if (!config) {
    return { ok: false, error: "unknown category" };
  }

  const loyaltyYears = req.loyaltyYears as number;
  if (!Number.isInteger(loyaltyYears) || loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const nights = req.nights as number;
  if (!Number.isInteger(nights) || nights < 1 || nights > config.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (config.minNights !== undefined && nights < config.minNights) {
    return { ok: false, error: `${config.code} minimum stay` };
  }

  const guests = req.guests as number;
  if (!Number.isInteger(guests) || guests < 1 || guests > config.maxGuests) {
    return { ok: false, error: "bad guests" };
  }

  const season = req.season as string;
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }

  return computeQuote({
    config,
    loyaltyYears,
    coupon: req.coupon,
    nights,
    guests,
    season,
  });
}

files.process_events.ts:
interface Want {
  item: string;
  qty: number;
}

type Stock = Record<string, number>;

interface RawEvent {
  type?: string;
  id?: unknown;
  item?: unknown;
  qty?: unknown;
}

interface WarehouseState {
  stock: Stock;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  orders: Record<string, string>;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type Parse<T> = { value: T } | { error: string };

function badInteger(value: unknown): boolean {
  return !Number.isInteger(value);
}

function parseId(event: RawEvent, index: number): Parse<string> {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return { error: "event " + index + ": bad id" };
  }
  return { value: event.id };
}

function parseItem(event: RawEvent, index: number): Parse<string> {
  if (typeof event.item !== "string" || event.item.length === 0) {
    return { error: "event " + index + ": bad item" };
  }
  return { value: event.item };
}

function parseQty(value: unknown, index: number, minimum: number): Parse<number> {
  if (badInteger(value) || (value as number) < minimum) {
    return { error: "event " + index + ": bad qty" };
  }
  return { value: value as number };
}

function parseShipQty(event: RawEvent, index: number): Parse<number | undefined> {
  if (event.qty !== undefined && (badInteger(event.qty) || (event.qty as number) < 1)) {
    return { error: "event " + index + ": bad qty" };
  }
  return { value: event.qty as number | undefined };
}

function stockOnHand(stock: Stock, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function fulfilFromQueue(state: WarehouseState): void {
  const { stock, reserved, pendingWants, queue, orders } = state;
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    const onHand = stockOnHand(stock, want.item);
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function reserve(state: WarehouseState, id: string, want: Want): void {
  const onHand = stockOnHand(state.stock, want.item);
  state.stock[want.item] = onHand - want.qty;
  state.reserved[id] = want;
  state.orders[id] = "reserved";
}

function backorder(state: WarehouseState, id: string, want: Want): void {
  state.pendingWants[id] = want;
  state.queue.push(id);
  state.orders[id] = "backordered";
}

function releaseReservation(state: WarehouseState, orderId: string, status: string): void {
  const holding = state.reserved[orderId];
  const back = stockOnHand(state.stock, holding.item);
  state.stock[holding.item] = back + holding.qty;
  delete state.reserved[orderId];
  state.orders[orderId] = status;
  fulfilFromQueue(state);
}

function placeOrder(state: WarehouseState, event: RawEvent, index: number): Parse<null> {
  const id = parseId(event, index);
  if ("error" in id) {
    return id;
  }
  if (state.orders[id.value] !== undefined) {
    return { error: "event " + index + ": duplicate order" };
  }
  const item = parseItem(event, index);
  if ("error" in item) {
    return item;
  }
  const qty = parseQty(event.qty, index, 1);
  if ("error" in qty) {
    return qty;
  }
  const want: Want = { item: item.value, qty: qty.value };
  if (stockOnHand(state.stock, want.item) >= want.qty) {
    reserve(state, id.value, want);
  } else {
    backorder(state, id.value, want);
  }
  return { value: null };
}

function cancelOrder(state: WarehouseState, event: RawEvent, index: number): Parse<boolean> {
  const id = parseId(event, index);
  if ("error" in id) {
    return id;
  }
  if (state.reserved[id.value] !== undefined) {
    releaseReservation(state, id.value, "cancelled");
    return { value: false };
  }
  if (state.orders[id.value] === "backordered") {
    state.queue.splice(state.queue.indexOf(id.value), 1);
    delete state.pendingWants[id.value];
    state.orders[id.value] = "cancelled";
    return { value: false };
  }
  return { value: true };
}

function shipOrder(state: WarehouseState, event: RawEvent, index: number): Parse<boolean> {
  const id = parseId(event, index);
  if ("error" in id) {
    return id;
  }
  const qty = parseShipQty(event, index);
  if ("error" in qty) {
    return qty;
  }
  const holding = state.reserved[id.value];
  if (holding === undefined) {
    return { value: true };
  }
  if (qty.value === undefined || qty.value === holding.qty) {
    delete state.reserved[id.value];
    state.orders[id.value] = "shipped";
    return { value: false };
  }
  if (qty.value < holding.qty) {
    holding.qty = holding.qty - qty.value;
    state.orders[id.value] = "partial";
    return { value: false };
  }
  return { value: true };
}

function restockItem(state: WarehouseState, event: RawEvent, index: number): Parse<null> {
  const item = parseItem(event, index);
  if ("error" in item) {
    return item;
  }
  const qty = parseQty(event.qty, index, 1);
  if ("error" in qty) {
    return qty;
  }
  state.stock[item.value] = stockOnHand(state.stock, item.value) + qty.value;
  fulfilFromQueue(state);
  return { value: null };
}

function expireOrder(state: WarehouseState, event: RawEvent, index: number): Parse<boolean> {
  const id = parseId(event, index);
  if ("error" in id) {
    return id;
  }
  if (state.reserved[id.value] === undefined) {
    return { value: true };
  }
  releaseReservation(state, id.value, "expired");
  return { value: false };
}

type Handler = (state: WarehouseState, event: RawEvent, index: number) => Parse<null> | Parse<boolean>;

const HANDLERS: Record<string, Handler> = {
  order: placeOrder,
  cancel: cancelOrder,
  ship: shipOrder,
  restock: restockItem,
  expire: expireOrder,
};

function parseStock(raw: unknown): Parse<Stock> {
  if (typeof raw !== "object" || raw === null) {
    return { error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { error: "bad stock" };
  }
  const rawStock = input.stock as Record<string, unknown>;
  const stock: Stock = {};
  for (const item of Object.keys(rawStock)) {
    if (badInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  return { value: stock };
}

function handleEvent(state: WarehouseState, event: RawEvent, index: number): Parse<null> | Parse<boolean> {
  const handler: Handler | undefined = event.type === undefined ? undefined : HANDLERS[event.type];
  if (handler === undefined) {
    return { error: "event " + index + ": bad type" };
  }
  return handler(state, event, index);
}

export function processEvents(raw: unknown): FulfillmentResult {
  const parsed = parseStock(raw);
  if ("error" in parsed) {
    return { ok: false, error: parsed.error };
  }
  if (!Array.isArray((raw as Record<string, unknown>).events)) {
    return { ok: false, error: "bad events" };
  }
  const events = (raw as Record<string, unknown>).events as unknown[];

  const state: WarehouseState = {
    stock: parsed.value,
    reserved: {},
    pendingWants: {},
    queue: [],
    orders: {},
  };
  let rejected = 0;

  for (let index = 0; index < events.length; index++) {
    const event = events[index] as RawEvent;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const result = handleEvent(state, event, index);
    if ("error" in result) {
      return { ok: false, error: result.error };
    }
    if (result.value === true) {
      rejected = rejected + 1;
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected,
    report: buildReport(state.orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  stock: Record<string, number>;
  queue: string[];
  rejected: number;
}

function onHand(stock: Record<string, number>, item: string): number {
  const held = stock[item];
  return held === undefined ? 0 : held;
}

function badId(event: Record<string, unknown>): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "bad id";
  }
  return null;
}

function badInt(event: Record<string, unknown>, field: string, min: number): string | null {
  const value = event[field];
  if (!Number.isInteger(value) || (value as number) < min) {
    return "bad " + field;
  }
  return null;
}

function fail(index: number, message: string): string {
  return "event " + index + ": " + message;
}

function drainBacklog(state: State): void {
  const { queue, pendingWants, reserved, stock, orders } = state;
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    if (onHand(stock, want.item) >= want.qty) {
      stock[want.item] = onHand(stock, want.item) - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function releaseHolding(state: State, id: string): void {
  const holding = state.reserved[id];
  if (holding === undefined) {
    return;
  }
  state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
  delete state.reserved[id];
}

type Handler = (state: State, event: Record<string, unknown>, index: number) => string | null;

function parseStock(input: Record<string, unknown>): { stock?: Record<string, number>; error?: string } {
  if (typeof input.stock !== "object" || input.stock === null) return { error: "bad stock" };
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  return { stock };
}

function handleOrder(state: State, event: Record<string, unknown>, index: number): string | null {
  const idError = badId(event);
  if (idError) return fail(index, idError);
  if (state.orders[event.id as string] !== undefined) return fail(index, "duplicate order");
  if (typeof event.item !== "string" || event.item.length === 0) return fail(index, "bad item");
  const qtyError = badInt(event, "qty", 1);
  if (qtyError) return fail(index, qtyError);
  const item = event.item;
  const qty = event.qty as number;
  if (onHand(state.stock, item) >= qty) {
    state.stock[item] = onHand(state.stock, item) - qty;
    state.reserved[event.id as string] = { item, qty };
    state.orders[event.id as string] = "reserved";
  } else {
    state.queue.push(event.id as string);
    state.pendingWants[event.id as string] = { item, qty };
    state.orders[event.id as string] = "backordered";
  }
  return null;
}

function handleCancel(state: State, event: Record<string, unknown>, index: number): string | null {
  const idError = badId(event);
  if (idError) return fail(index, idError);
  const id = event.id as string;
  if (state.reserved[id] !== undefined) {
    releaseHolding(state, id);
    state.orders[id] = "cancelled";
    drainBacklog(state);
  } else if (state.orders[id] === "backordered") {
    state.queue.splice(state.queue.indexOf(id), 1);
    delete state.pendingWants[id];
    state.orders[id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function handleShip(state: State, event: Record<string, unknown>, index: number): string | null {
  const idError = badId(event);
  if (idError) return fail(index, idError);
  if (event.qty !== undefined && badInt(event, "qty", 1)) return fail(index, "bad qty");
  const id = event.id as string;
  const held = state.reserved[id];
  if (held === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === held.qty) {
    delete state.reserved[id];
    state.orders[id] = "shipped";
  } else if ((event.qty as number) < held.qty) {
    held.qty = held.qty - (event.qty as number);
    state.orders[id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function handleRestock(state: State, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.item !== "string" || event.item.length === 0) return fail(index, "bad item");
  const qtyError = badInt(event, "qty", 1);
  if (qtyError) return fail(index, qtyError);
  const item = event.item;
  state.stock[item] = onHand(state.stock, item) + (event.qty as number);
  drainBacklog(state);
  return null;
}

function handleExpire(state: State, event: Record<string, unknown>, index: number): string | null {
  const idError = badId(event);
  if (idError) return fail(index, idError);
  const id = event.id as string;
  if (state.reserved[id] !== undefined) {
    releaseHolding(state, id);
    state.orders[id] = "expired";
    drainBacklog(state);
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) return { ok: false, error: "malformed input" };
  const input = raw as Record<string, unknown>;

  const parsed = parseStock(input);
  if (parsed.error) return { ok: false, error: parsed.error };
  const stock = parsed.stock as Record<string, number>;

  if (!Array.isArray(input.events)) return { ok: false, error: "bad events" };

  const state: State = {
    orders: {},
    reserved: {},
    pendingWants: {},
    stock,
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) return { ok: false, error: fail(index, "malformed") };
    const handler = HANDLERS[event.type as string];
    if (!handler) return { ok: false, error: fail(index, "bad type") };
    const error = handler(state, event, index);
    if (error) return { ok: false, error: error };
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface FulfillmentState {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

interface ParsedInput {
  stock: Record<string, number>;
  events: Record<string, unknown>[];
}

export function processEvents(raw: unknown): FulfillmentResult {
  const result = parseInput(raw);
  if ("error" in result) {
    return { ok: false, error: result.error };
  }
  const { parsed } = result;

  const state: FulfillmentState = {
    stock: parsed.stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  const eventError = runEvents(parsed.events, state);
  if (eventError !== undefined) {
    return { ok: false, error: eventError };
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

type ParseResult = { parsed: ParsedInput } | { error: string };

function parseInput(raw: unknown): ParseResult {
  if (typeof raw !== "object" || raw === null) {
    return { error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { error: "bad events" };
  }
  const stock = readStock(input.stock as Record<string, unknown>);
  if (stock === null) {
    return { error: "bad stock" };
  }
  return { parsed: { stock, events: input.events as Record<string, unknown>[] } };
}

function readStock(raw: Record<string, unknown>): Record<string, number> | null {
  const stock: Record<string, number> = {};
  for (const item of Object.keys(raw)) {
    if (!Number.isInteger(raw[item]) || (raw[item] as number) < 0) {
      return null;
    }
    stock[item] = raw[item] as number;
  }
  return stock;
}

function runEvents(
  events: Record<string, unknown>[],
  state: FulfillmentState
): string | undefined {
  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (typeof event !== "object" || event === null) {
      return "event " + index + ": malformed";
    }
    const error = handleEvent(event as Record<string, unknown>, index, state);
    if (error !== undefined) {
      return error;
    }
  }
  return undefined;
}

function handleEvent(
  event: Record<string, unknown>,
  index: number,
  state: FulfillmentState
): string | undefined {
  const handler = HANDLERS[event.type as string];
  if (handler === undefined) {
    return "event " + index + ": bad type";
  }
  return handler(event, index, state);
}

function requireId(
  event: Record<string, unknown>,
  index: number
): string | undefined {
  return typeof event.id === "string" && event.id.length > 0
    ? undefined
    : "event " + index + ": bad id";
}

function requireQty(
  qty: unknown,
  index: number,
  error: string
): string | undefined {
  return Number.isInteger(qty) && (qty as number) > 0
    ? undefined
    : "event " + index + ": " + error;
}

function itemOf(
  event: Record<string, unknown>,
  index: number
): string | undefined {
  return typeof event.item === "string" && event.item.length > 0
    ? event.item
    : undefined;
}

function itemErr(index: number): string {
  return "event " + index + ": bad item";
}

function qtyErr(index: number): string {
  return "event " + index + ": bad qty";
}

function onHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function handleOrder(
  event: Record<string, unknown>,
  index: number,
  state: FulfillmentState
): string | undefined {
  const idError = requireId(event, index);
  if (idError !== undefined) {
    return idError;
  }
  const id = event.id as string;
  if (state.orders[id] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  const item = itemOf(event, index);
  if (item === undefined) {
    return itemErr(index);
  }
  const qtyError = requireQty(event.qty, index, "bad qty");
  if (qtyError !== undefined) {
    return qtyError;
  }
  const qty = event.qty as number;
  const want: Want = { item, qty };
  if (onHand(state.stock, item) >= qty) {
    state.stock[item] = onHand(state.stock, item) - qty;
    state.reserved[id] = want;
    state.orders[id] = "reserved";
  } else {
    state.queue.push(id);
    state.pendingWants[id] = want;
    state.orders[id] = "backordered";
  }
  return undefined;
}

function handleCancel(
  event: Record<string, unknown>,
  index: number,
  state: FulfillmentState
): string | undefined {
  const idError = requireId(event, index);
  if (idError !== undefined) {
    return idError;
  }
  const id = event.id as string;
  if (state.reserved[id] !== undefined) {
    const holding = state.reserved[id];
    state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
    delete state.reserved[id];
    state.orders[id] = "cancelled";
    tryFulfillQueue(state);
  } else if (state.orders[id] === "backordered") {
    state.queue.splice(state.queue.indexOf(id), 1);
    delete state.pendingWants[id];
    state.orders[id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return undefined;
}

function handleShip(
  event: Record<string, unknown>,
  index: number,
  state: FulfillmentState
): string | undefined {
  const idError = requireId(event, index);
  if (idError !== undefined) {
    return idError;
  }
  const id = event.id as string;
  const qtyError = requireQty(event.qty, index, "bad qty");
  if (qtyError !== undefined && event.qty !== undefined) {
    return qtyError;
  }
  const qty = event.qty as number | undefined;
  const held = state.reserved[id];
  if (held === undefined) {
    state.rejected = state.rejected + 1;
  } else if (qty === undefined || qty === held.qty) {
    delete state.reserved[id];
    state.orders[id] = "shipped";
  } else if (qty < held.qty) {
    held.qty = held.qty - qty;
    state.orders[id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
  return undefined;
}

function handleRestock(
  event: Record<string, unknown>,
  index: number,
  state: FulfillmentState
): string | undefined {
  const item = itemOf(event, index);
  if (item === undefined) {
    return itemErr(index);
  }
  const qtyError = requireQty(event.qty, index, "bad qty");
  if (qtyError !== undefined) {
    return qtyError;
  }
  state.stock[item] = onHand(state.stock, item) + (event.qty as number);
  tryFulfillQueue(state);
  return undefined;
}

function handleExpire(
  event: Record<string, unknown>,
  index: number,
  state: FulfillmentState
): string | undefined {
  const idError = requireId(event, index);
  if (idError !== undefined) {
    return idError;
  }
  const id = event.id as string;
  if (state.reserved[id] !== undefined) {
    const holding = state.reserved[id];
    state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
    delete state.reserved[id];
    state.orders[id] = "expired";
    tryFulfillQueue(state);
  } else {
    state.rejected = state.rejected + 1;
  }
  return undefined;
}

function tryFulfillQueue(state: FulfillmentState): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const available = onHand(state.stock, want.item);
    if (available >= want.qty) {
      state.stock[want.item] = available - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

const HANDLERS: Record<string, EventHandler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

type EventHandler = (
  event: Record<string, unknown>,
  index: number,
  state: FulfillmentState
) => string | undefined;

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

type EventRecord = Record<string, unknown>;

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

function onHand(stock: Record<string, number>, item: string): number {
  const held = stock[item];
  return held === undefined ? 0 : held;
}

function tryFulfillQueue(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const held = onHand(state.stock, want.item);
    if (held >= want.qty) {
      state.stock[want.item] = held - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function releaseReservation(state: State, id: string, status: string): void {
  const holding = state.reserved[id];
  state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
  delete state.reserved[id];
  state.orders[id] = status;
  tryFulfillQueue(state);
}

function requireId(ev: EventRecord): string | null {
  return typeof ev.id === "string" && (ev.id as string).length > 0
    ? null
    : "bad id";
}

function requireItem(ev: EventRecord): string | null {
  return typeof ev.item === "string" && (ev.item as string).length > 0
    ? null
    : "bad item";
}

function requireQty(ev: EventRecord): string | null {
  return Number.isInteger(ev.qty) && (ev.qty as number) >= 1
    ? null
    : "bad qty";
}

function placeOrder(state: State, ev: EventRecord): string | null {
  let problem: string | null;
  if ((problem = requireId(ev)) !== null) return problem;
  const id = ev.id as string;
  if (state.orders[id] !== undefined) {
    return "duplicate order";
  }
  if ((problem = requireItem(ev)) !== null) return problem;
  if ((problem = requireQty(ev)) !== null) return problem;
  const qty = ev.qty as number;
  const item = ev.item as string;
  const held = onHand(state.stock, item);
  if (held >= qty) {
    state.stock[item] = held - qty;
    state.reserved[id] = { item, qty };
    state.orders[id] = "reserved";
  } else {
    state.queue.push(id);
    state.pendingWants[id] = { item, qty };
    state.orders[id] = "backordered";
  }
  return null;
}

function cancelOrder(state: State, ev: EventRecord): string | null {
  let problem: string | null;
  if ((problem = requireId(ev)) !== null) return problem;
  const id = ev.id as string;
  if (state.reserved[id] !== undefined) {
    releaseReservation(state, id, "cancelled");
  } else if (state.orders[id] === "backordered") {
    state.queue.splice(state.queue.indexOf(id), 1);
    delete state.pendingWants[id];
    state.orders[id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function applyShipment(state: State, id: string, qty: number): void {
  if (qty === state.reserved[id].qty) {
    delete state.reserved[id];
    state.orders[id] = "shipped";
  } else {
    state.reserved[id].qty = state.reserved[id].qty - qty;
    state.orders[id] = "partial";
  }
}

function shipOrder(state: State, ev: EventRecord): string | null {
  const problem = requireId(ev);
  if (problem !== null) return problem;
  const id = ev.id as string;
  const shipQty = ev.qty as number | undefined;
  if (shipQty !== undefined && (!Number.isInteger(shipQty) || shipQty < 1)) {
    return "bad qty";
  }
  const reservation = state.reserved[id];
  if (reservation === undefined) {
    state.rejected = state.rejected + 1;
    return null;
  }
  const qty = shipQty === undefined ? reservation.qty : shipQty;
  if (qty > reservation.qty) {
    state.rejected = state.rejected + 1;
    return null;
  }
  applyShipment(state, id, qty);
  return null;
}

function restockItem(state: State, ev: EventRecord): string | null {
  let problem: string | null;
  if ((problem = requireItem(ev)) !== null) return problem;
  if ((problem = requireQty(ev)) !== null) return problem;
  const item = ev.item as string;
  const qty = ev.qty as number;
  state.stock[item] = onHand(state.stock, item) + qty;
  tryFulfillQueue(state);
  return null;
}

function expireOrder(state: State, ev: EventRecord): string | null {
  let problem: string | null;
  if ((problem = requireId(ev)) !== null) return problem;
  const id = ev.id as string;
  if (state.reserved[id] !== undefined) {
    releaseReservation(state, id, "expired");
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

const HANDLERS: Record<string, (state: State, ev: EventRecord) => string | null> = {
  order: placeOrder,
  cancel: cancelOrder,
  ship: shipOrder,
  restock: restockItem,
  expire: expireOrder,
};

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

function parseStock(raw: Record<string, unknown>):
  | { stock: Record<string, number> }
  | { error: string } {
  if (typeof raw.stock !== "object" || raw.stock === null) {
    return { error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = raw.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  return { stock };
}

function parseInput(raw: unknown): { state?: State; events?: unknown[]; error?: string } {
  if (typeof raw !== "object" || raw === null) {
    return { error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  const stockResult = parseStock(input);
  if ("error" in stockResult) {
    return { error: stockResult.error };
  }
  if (!Array.isArray(input.events)) {
    return { error: "bad events" };
  }
  const state: State = {
    stock: stockResult.stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };
  return { state, events: input.events };
}

export function processEvents(raw: unknown): FulfillmentResult {
  const parsed = parseInput(raw);
  if (parsed.error !== undefined) {
    return { ok: false, error: parsed.error };
  }
  const state = parsed.state as State;
  const events = (raw as Record<string, unknown>).events as unknown[];

  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const ev = event as EventRecord;
    const handler = HANDLERS[ev.type as string];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const problem = handler(state, ev);
    if (problem !== null) {
      return { ok: false, error: "event " + index + ": " + problem };
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type Problem = string;

function isId(s: unknown): s is string {
  return typeof s === "string" && s.length > 0;
}

function isQty(n: unknown): boolean {
  return Number.isInteger(n) && (n as number) >= 1;
}

function isItem(s: unknown): s is string {
  return typeof s === "string" && s.length > 0;
}

class State {
  readonly stock: Record<string, number> = {};
  readonly orders: Record<string, string> = {};
  readonly reserved: Record<string, Want> = {};
  readonly pendingWants: Record<string, Want> = {};
  readonly queue: string[] = [];
  rejected = 0;

  onHand(item: string): number {
    const qty = this.stock[item];
    return qty === undefined ? 0 : qty;
  }

  reserve(id: string, want: Want): void {
    this.stock[want.item] = this.onHand(want.item) - want.qty;
    this.reserved[id] = { item: want.item, qty: want.qty };
    this.orders[id] = "reserved";
  }

  settleQueue(): void {
    for (let position = 0; position < this.queue.length; position++) {
      const pendingId = this.queue[position];
      const want = this.pendingWants[pendingId];
      const onHand = this.onHand(want.item);
      if (onHand < want.qty) {
        continue;
      }
      this.reserve(pendingId, want);
      delete this.pendingWants[pendingId];
      this.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function order(state: State, event: Record<string, unknown>): Problem | undefined {
  if (!isId(event.id)) {
    return "bad id";
  }
  if (state.orders[event.id] !== undefined) {
    return "duplicate order";
  }
  if (!isItem(event.item)) {
    return "bad item";
  }
  if (!isQty(event.qty)) {
    return "bad qty";
  }
  const want: Want = { item: event.item, qty: event.qty as number };
  if (state.onHand(want.item) >= want.qty) {
    state.reserve(event.id, want);
  } else {
    state.queue.push(event.id);
    state.pendingWants[event.id] = want;
    state.orders[event.id] = "backordered";
  }
}

function cancel(state: State, event: Record<string, unknown>): Problem | undefined {
  if (!isId(event.id)) {
    return "bad id";
  }
  if (state.reserved[event.id] !== undefined) {
    const holding = state.reserved[event.id];
    state.stock[holding.item] = state.onHand(holding.item) + holding.qty;
    delete state.reserved[event.id];
    state.orders[event.id] = "cancelled";
    state.settleQueue();
  } else if (state.orders[event.id] === "backordered") {
    state.queue.splice(state.queue.indexOf(event.id), 1);
    delete state.pendingWants[event.id];
    state.orders[event.id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
}

function ship(state: State, event: Record<string, unknown>): Problem | undefined {
  if (!isId(event.id)) {
    return "bad id";
  }
  if (event.qty !== undefined && !isQty(event.qty)) {
    return "bad qty";
  }
  const held = state.reserved[event.id];
  if (held === undefined) {
    state.rejected = state.rejected + 1;
    return;
  }
  const shipped = event.qty === undefined ? held.qty : (event.qty as number);
  if (shipped < held.qty) {
    held.qty = held.qty - shipped;
    state.orders[event.id] = "partial";
  } else if (shipped > held.qty) {
    state.rejected = state.rejected + 1;
  } else {
    delete state.reserved[event.id];
    state.orders[event.id] = "shipped";
  }
}

function restock(state: State, event: Record<string, unknown>): Problem | undefined {
  if (!isItem(event.item)) {
    return "bad item";
  }
  if (!isQty(event.qty)) {
    return "bad qty";
  }
  state.stock[event.item] = state.onHand(event.item) + (event.qty as number);
  state.settleQueue();
}

function expire(state: State, event: Record<string, unknown>): Problem | undefined {
  if (!isId(event.id)) {
    return "bad id";
  }
  if (state.reserved[event.id] !== undefined) {
    const holding = state.reserved[event.id];
    state.stock[holding.item] = state.onHand(holding.item) + holding.qty;
    delete state.reserved[event.id];
    state.orders[event.id] = "expired";
    state.settleQueue();
  } else {
    state.rejected = state.rejected + 1;
  }
}

type Handler = (state: State, event: Record<string, unknown>) => Problem | undefined;

const HANDLERS: Record<string, Handler> = {
  order,
  cancel,
  ship,
  restock,
  expire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  const input = parseload(raw);
  if (input.error !== undefined) {
    return { ok: false, error: input.error };
  }
  const state = new State();
  Object.assign(state.stock, input.stock);
  for (let index = 0; index < input.events!.length; index++) {
    const event = input.events![index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = HANDLERS[event.type as string];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const problem = handler(state, event);
    if (problem !== undefined) {
      return { ok: false, error: "event " + index + ": " + problem };
    }
  }
  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

function checkShape(raw: unknown): Record<string, unknown> | undefined {
  return typeof raw === "object" && raw !== null ? (raw as Record<string, unknown>) : undefined;
}

function checkStock(raw: unknown): Record<string, number> | undefined {
  if (typeof raw !== "object" || raw === null) {
    return undefined;
  }
  const stock: Record<string, number> = {};
  for (const [item, value] of Object.entries(raw as Record<string, unknown>)) {
    if (!Number.isInteger(value) || (value as number) < 0) {
      return undefined;
    }
    stock[item] = value as number;
  }
  return stock;
}

function parseload(raw: unknown): { error?: string; stock?: Record<string, number>; events?: unknown[] } {
  const input = checkShape(raw);
  if (input === undefined) {
    return { error: "malformed input" };
  }
  const stock = checkStock(input.stock);
  if (stock === undefined) {
    return { error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { error: "bad events" };
  }
  return { stock, events: input.events };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"] as const;
type Status = (typeof STATUSES)[number];

function statusCounts(orders: Record<string, string>): Record<Status, number> {
  const counts: Record<Status, number> = {} as Record<Status, number>;
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id] as Status] = counts[orders[id] as Status] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface Context {
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  stock: Record<string, number>;
  rejected: number;
}

type Handler = (ev: Record<string, unknown>, ctx: Context, index: number) => string | null;

function requireId(ev: Record<string, unknown>, index: number): string | null {
  return typeof ev.id === "string" && ev.id.length > 0 ? null : "event " + index + ": bad id";
}

function requireItem(ev: Record<string, unknown>, index: number): string | null {
  return typeof ev.item === "string" && ev.item.length > 0 ? null : "event " + index + ": bad item";
}

function requirePositive(ev: Record<string, unknown>, index: number): string | null {
  return Number.isInteger(ev.qty) && (ev.qty as number) >= 1 ? null : "event " + index + ": bad qty";
}

function onHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function returnStock(want: Want, ctx: Context): void {
  ctx.stock[want.item] = onHand(ctx.stock, want.item) + want.qty;
}

function attemptFill(ctx: Context): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    if (onHand(ctx.stock, want.item) >= want.qty) {
      ctx.stock[want.item] = ctx.stock[want.item] - want.qty;
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function handleOrder(ev: Record<string, unknown>, ctx: Context, index: number): string | null {
  const idErr = requireId(ev, index);
  if (idErr !== null) return idErr;
  if (ctx.orders[ev.id as string] !== undefined) return "event " + index + ": duplicate order";
  const itemErr = requireItem(ev, index);
  if (itemErr !== null) return itemErr;
  const qtyErr = requirePositive(ev, index);
  if (qtyErr !== null) return qtyErr;
  const id = ev.id as string;
  const want = { item: ev.item as string, qty: ev.qty as number };
  if (onHand(ctx.stock, want.item) >= want.qty) {
    ctx.stock[want.item] = ctx.stock[want.item] - want.qty;
    ctx.reserved[id] = want;
    ctx.orders[id] = "reserved";
  } else {
    ctx.orders[id] = "backordered";
    ctx.pendingWants[id] = want;
    ctx.queue.push(id);
  }
  return null;
}

function handleCancel(ev: Record<string, unknown>, ctx: Context, index: number): string | null {
  const idErr = requireId(ev, index);
  if (idErr !== null) return idErr;
  const id = ev.id as string;
  if (ctx.reserved[id] !== undefined) {
    returnStock(ctx.reserved[id], ctx);
    delete ctx.reserved[id];
    ctx.orders[id] = "cancelled";
    attemptFill(ctx);
  } else if (ctx.orders[id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(id), 1);
    delete ctx.pendingWants[id];
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function handleShip(ev: Record<string, unknown>, ctx: Context, index: number): string | null {
  const idErr = requireId(ev, index);
  if (idErr !== null) return idErr;
  if (ev.qty !== undefined && !(Number.isInteger(ev.qty) && (ev.qty as number) >= 1)) {
    return "event " + index + ": bad qty";
  }
  const id = ev.id as string;
  const held = ctx.reserved[id];
  if (held === undefined) {
    ctx.rejected = ctx.rejected + 1;
    return null;
  }
  const qty = ev.qty === undefined ? held.qty : (ev.qty as number);
  if (qty > held.qty) {
    ctx.rejected = ctx.rejected + 1;
    return null;
  }
  if (qty === held.qty) {
    delete ctx.reserved[id];
    ctx.orders[id] = "shipped";
  } else {
    held.qty = held.qty - qty;
    ctx.orders[id] = "partial";
  }
  return null;
}

function handleRestock(ev: Record<string, unknown>, ctx: Context, index: number): string | null {
  const itemErr = requireItem(ev, index);
  if (itemErr !== null) return itemErr;
  const qtyErr = requirePositive(ev, index);
  if (qtyErr !== null) return qtyErr;
  const item = ev.item as string;
  ctx.stock[item] = onHand(ctx.stock, item) + (ev.qty as number);
  attemptFill(ctx);
  return null;
}

function handleExpire(ev: Record<string, unknown>, ctx: Context, index: number): string | null {
  const idErr = requireId(ev, index);
  if (idErr !== null) return idErr;
  const id = ev.id as string;
  if (ctx.reserved[id] !== undefined) {
    returnStock(ctx.reserved[id], ctx);
    delete ctx.reserved[id];
    ctx.orders[id] = "expired";
    attemptFill(ctx);
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

const HANDLERS: Record<string, Handler> = {
  order: (ev, ctx, index) => handleOrder(ev, ctx, index),
  cancel: (ev, ctx, index) => handleCancel(ev, ctx, index),
  ship: (ev, ctx, index) => handleShip(ev, ctx, index),
  restock: (ev, ctx, index) => handleRestock(ev, ctx, index),
  expire: (ev, ctx, index) => handleExpire(ev, ctx, index),
};

function applyEvent(event: unknown, ctx: Context, index: number): string | null {
  if (typeof event !== "object" || event === null) {
    return "event " + index + ": malformed";
  }
  const ev = event as Record<string, unknown>;
  const handler = HANDLERS[ev.type as string];
  if (handler === undefined) {
    return "event " + index + ": bad type";
  }
  return handler(ev, ctx, index);
}

function runEvents(events: unknown[], ctx: Context): string | null {
  for (let index = 0; index < events.length; index++) {
    const error = applyEvent(events[index], ctx, index);
    if (error !== null) {
      return error;
    }
  }
  return null;
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

function readStock(rawStock: Record<string, unknown>, stock: Record<string, number>): string | null {
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return "bad stock";
    }
    stock[item] = rawStock[item] as number;
  }
  return null;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const stockErr = readStock(input.stock as Record<string, unknown>, stock);
  if (stockErr !== null) {
    return { ok: false, error: stockErr };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const ctx: Context = {
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    stock,
    rejected: 0,
  };

  const eventsError = runEvents(input.events as unknown[], ctx);
  if (eventsError !== null) {
    return { ok: false, error: eventsError };
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

