import { processEvents as orig } from './orig_src/index';
import { processEvents as imp } from './imp/index';

function rand(n: number) { return Math.floor(Math.random() * n); }

for (let trial = 0; trial < 200000; trial++) {
  const items = ["a", "b", "c"];
  const stock: Record<string, number> = {};
  for (const it of items) { stock[it] = rand(8); }
  const events: any[] = [];
  const n = rand(15);
  for (let i = 0; i < n; i++) {
    const type = ["order", "order", "order", "cancel", "ship", "restock", "restock", "expire"][rand(8)];
    switch (type) {
      case "order": events.push({ type, id: "id" + rand(6), item: items[rand(3)], qty: 1 + rand(8) }); break;
      case "cancel": events.push({ type, id: "id" + rand(6) }); break;
      case "ship": { const e: any = { type, id: "id" + rand(6) }; if (rand(3) === 0) e.qty = 1 + rand(8); events.push(e); break; }
      case "restock": events.push({ type, item: items[rand(3)], qty: 1 + rand(8) }); break;
      case "expire": events.push({ type, id: "id" + rand(6) }); break;
    }
  }
  const input = rand(100) < 4 ? (rand(2) ? null : { stock: { a: -1 }, events: [] }) : { stock, events };
  const a = orig(input);
  const b = imp(input);
  const ja = JSON.stringify(a), jb = JSON.stringify(b);
  if (ja !== jb) {
    console.log("MISMATCH trial", trial, JSON.stringify(input));
    console.log("orig:", ja);
    console.log("imp :", jb);
    process.exit(1);
  }
}
console.log("ALL OK");

