    ctx.pendingWants[id] = { item, qty };
    ctx.orders[id] = "backordered";
  }
  return null;
}

function handleCancel(ctx: Context, event: Record<string, unknown>, index: number): string | null {
  const id = getId(event);
  if (id === null) return eventLabel(index) + ": bad id";
  if (ctx.reserved[id] !== undefined) {
    releaseReservation(ctx, id, "cancelled");
  } else if (ctx.orders[id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(id), 1);
    delete ctx.pendingWants[id];
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function handleShip(ctx: Context, event: Record<string, unknown>, index: number): string | null {
  const id = getId(event);
  if (id === null) return eventLabel(index) + ": bad id";
  if (event.qty !== undefined && !validQty(event.qty, true)) {
    return eventLabel(index) + ": bad qty";
  }
  const holding = ctx.reserved[id];
  if (holding === undefined) {
    ctx.rejected = ctx.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === holding.qty) {
    delete ctx.reserved[id];
    ctx.orders[id] = "shipped";
  } else if ((event.qty as number) < holding.qty) {
    holding.qty = holding.qty - (event.qty as number);
    ctx.orders[id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function handleRestock(ctx: Context, event: Record<string, unknown>, index: number): string | null {
  const item = getItem(event);
  if (item === null) return eventLabel(index) + ": bad item";
  if (!validQty(event.qty, true)) return eventLabel(index) + ": bad qty";
  ctx.stock[item] = onHand(ctx.stock, item) + (event.qty as number);
  drainQueue(ctx);
  return null;
}

function handleExpire(ctx: Context, event: Record<string, unknown>, index: number): string | null {
  const id = getId(event);
  if (id === null) return eventLabel(index) + ": bad id";
  if (ctx.reserved[id] !== undefined) {
    releaseReservation(ctx, id, "expired");
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

type Handler = (ctx: Context, event: Record<string, unknown>, index: number) => string | null;

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

function runEvents(events: unknown[], ctx: Context): string | null {
  for (let index = 0; index < events.length; index++) {
    const event = events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return eventLabel(index) + ": malformed";
    }
    const handler = HANDLERS[event.type as string];
    if (handler === undefined) {
      return eventLabel(index) + ": bad type";
    }
    const error = handler(ctx, event, index);
    if (error !== null) {
      return error;
    }
  }
  return null;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) return { ok: false, error: "malformed input" };
  const input = raw as Record<string, unknown>;
  const stock = parseStock(input.stock);
  if (stock === null) return { ok: false, error: "bad stock" };
  if (!Array.isArray(input.events)) return { ok: false, error: "bad events" };

  const ctx: Context = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };
  const error = runEvents(input.events as unknown[], ctx);
  if (error !== null) {
    return { ok: false, error };
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

