interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

interface OrderEvent {
  id: string;
  item: string;
  qty: number;
}

function onHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function validId(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function validQty(value: unknown): value is number {
  return Number.isInteger(value) && (value as number) >= 1;
}

function parseOrder(event: Record<string, unknown>, order: OrderEvent): string | undefined {
  if (!validId(event.id)) return "bad id";
  if (typeof event.item !== "string" || event.item.length === 0) return "bad item";
  if (!validQty(event.qty)) return "bad qty";
  order.id = event.id;
  order.item = event.item;
  order.qty = event.qty;
}

function hold(orderId: string, item: string, qty: number, state: State): void {
  state.stock[item] = onHand(state.stock, item) - qty;
  state.reserved[orderId] = { item, qty };
  state.orders[orderId] = "reserved";
}

function backorder(orderId: string, item: string, qty: number, state: State): void {
  state.queue.push(orderId);
  state.pendingWants[orderId] = { item, qty };
  state.orders[orderId] = "backordered";
}

function fulfillQueue(state: State): void {
  let position = 0;
  while (position < state.queue.length) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    if (onHand(state.stock, want.item) >= want.qty) {
      hold(pendingId, want.item, want.qty, state);
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
    } else {
      position = position + 1;
    }
  }
}

function releaseReserved(orderId: string, status: string, state: State): void {
  const holding = state.reserved[orderId];
  state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
  delete state.reserved[orderId];
  state.orders[orderId] = status;
  fulfillQueue(state);
}

function handleOrder(event: Record<string, unknown>, state: State): string | undefined {
  const order: OrderEvent = { id: "", item: "", qty: 0 };
  const problem = parseOrder(event, order);
  if (problem !== undefined) return problem;
  if (state.orders[order.id] !== undefined) return "duplicate order";
  if (onHand(state.stock, order.item) >= order.qty) {
    hold(order.id, order.item, order.qty, state);
  } else {
    backorder(order.id, order.item, order.qty, state);
  }
}

function handleCancel(event: Record<string, unknown>, state: State): string | undefined {
  if (!validId(event.id)) return "bad id";
  if (state.reserved[event.id] !== undefined) {
    releaseReserved(event.id, "cancelled", state);
  } else if (state.orders[event.id] === "backordered") {
    state.queue.splice(state.queue.indexOf(event.id), 1);
    delete state.pendingWants[event.id];
    state.orders[event.id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
}

function handleShip(event: Record<string, unknown>, state: State): string | undefined {
  if (!validId(event.id)) return "bad id";
  if (event.qty !== undefined && !validQty(event.qty)) return "bad qty";
  const holding = state.reserved[event.id];
  if (holding === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || event.qty === holding.qty) {
    delete state.reserved[event.id];
    state.orders[event.id] = "shipped";
  } else if ((event.qty as number) < holding.qty) {
    holding.qty = holding.qty - (event.qty as number);
    state.orders[event.id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
}

function handleRestock(event: Record<string, unknown>, state: State): string | undefined {
  if (typeof event.item !== "string" || event.item.length === 0) return "bad item";
  if (!validQty(event.qty)) return "bad qty";
  state.stock[event.item] = onHand(state.stock, event.item) + (event.qty as number);
  fulfillQueue(state);
}

function handleExpire(event: Record<string, unknown>, state: State): string | undefined {
  if (!validId(event.id)) return "bad id";
  if (state.reserved[event.id] !== undefined) {
    releaseReserved(event.id, "expired", state);
  } else {
    state.rejected = state.rejected + 1;
  }
}

const HANDLERS: Record<
  string,
  (event: Record<string, unknown>, state: State) => string | undefined
> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: State = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const type = typeof event.type === "string" ? event.type : "";
    const handler = HANDLERS[type];
    if (!handler) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const problem = handler(event, state);
    if (problem !== undefined) {
      return { ok: false, error: "event " + index + ": " + problem };
    }
  }

  const { orders, rejected } = state;
  return {
    ok: true,
    orders,
    stock,
    queue: state.queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

