export interface Reading {
  channel: string;
  unit: string;
  value: number;
  at: number;
}

interface ParsedReading {
  channel: string;
  millivolts: number;
  at: number;
}

interface ChannelSummary {
  count: number;
  min: number;
  max: number;
  worst: string;
}

export interface BatchResult {
  ok: boolean;
  error?: string;
  readings?: number;
  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts?: string[];
  report?: string;
}

const MAX_READINGS = 500;
const UNITS = ["uV", "mV", "V"] as const;
type Unit = (typeof UNITS)[number];

const STANDBY_LIMIT = 50;
const IDLE_LIMIT = 200;
const ACTIVE_LIMIT = 600;
const LOADED_LIMIT = 900;

const LABEL_RANK: Record<string, number> = {
  standby: 0,
  idle: 1,
  active: 2,
  loaded: 3,
  critical: 4,
  negative: 5,
};

type ParsedOutcome = { ok: true; reading: Reading } | { ok: false; error: string };

export function processBatch(raw: unknown): BatchResult {
  const batchError = validateBatch(raw);
  if (batchError !== null) {
    return { ok: false, error: batchError };
  }
  const entries = (raw as { readings: unknown[] }).readings;
  const parsed: ParsedReading[] = [];
  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
    if (!outcome.ok) {
      return { ok: false, error: outcome.error };
    }
    const reading = outcome.reading;
    parsed.push({
      channel: reading.channel,
      millivolts: normalizeValue(reading.unit, reading.value),
      at: reading.at,
    });
  }
  const labels = parsed.map((reading) => classifySignal(reading.millivolts));
  const alerts = collectAlerts(parsed, labels);
  const channels = channelSummaries(parsed, labels);
  const report = buildReport(parsed.length, Object.keys(channels).length, alerts.length, labels);
  return { ok: true, readings: parsed.length, labels, channels, alerts, report };
}

function validateBatch(raw: unknown): string | null {
  if (typeof raw !== "object" || raw === null) {
    return "malformed batch";
  }
  const batch = raw as Record<string, unknown>;
  if (!Array.isArray(batch.readings)) {
    return "missing readings";
  }
  if (batch.readings.length === 0) {
    return "empty batch";
  }
  if (batch.readings.length > MAX_READINGS) {
    return "batch too large";
  }
  return null;
}

function parseReading(entry: unknown, index: number): ParsedOutcome {
  if (typeof entry !== "object" || entry === null) {
    return { ok: false, error: "reading " + index + ": malformed" };
  }
  const { channel, unit, value, at } = entry as Record<string, unknown>;
  if (typeof channel !== "string" || channel.length === 0) {
    return { ok: false, error: "reading " + index + ": bad channel" };
  }
  if (!isSupportedUnit(unit)) {
    return { ok: false, error: "reading " + index + ": bad unit" };
  }
  if (!Number.isInteger(value)) {
    return { ok: false, error: "reading " + index + ": bad value" };
  }
  if (!isNonNegativeInt(at)) {
    return { ok: false, error: "reading " + index + ": bad timestamp" };
  }
  return { ok: true, reading: { channel, unit, value: value as number, at: at as number } };
}

function isSupportedUnit(value: unknown): value is Unit {
  return typeof value === "string" && (UNITS as readonly string[]).includes(value);
}

function isNonNegativeInt(value: unknown): boolean {
  return Number.isInteger(value) && (value as number) >= 0;
}

function normalizeValue(unit: string, value: number): number {
  switch (unit) {
    case "V":
      return value * 1000;
    case "uV":
      return Math.trunc(value / 1000);
    default:
      return value;
  }
}

export function classifySignal(millivolts: number): string {
  if (millivolts >= LOADED_LIMIT) {
    return "critical";
  }
  if (millivolts >= ACTIVE_LIMIT) {
    return "loaded";
  }
  if (millivolts >= IDLE_LIMIT) {
    return "active";
  }
  if (millivolts >= STANDBY_LIMIT) {
    return "idle";
  }
  if (millivolts >= 0) {
    return "standby";
  }
  return "negative";
}

function rankOf(label: string): number {
  return LABEL_RANK[label] ?? 0;
}

function collectAlerts(parsed: ParsedReading[], labels: string[]): string[] {
  const alerts: string[] = [];
  for (let index = 0; index < parsed.length; index++) {
    const label = labels[index];
    if (label === "loaded" || label === "critical" || label === "negative") {
      alerts.push(parsed[index].channel + ":" + label);
    }
  }
  return alerts;
}

function channelSummaries(parsed: ParsedReading[], labels: string[]): Record<string, ChannelSummary> {
  const channels: Record<string, ChannelSummary> = {};
  for (let index = 0; index < parsed.length; index++) {
    const reading = parsed[index];
    const label = labels[index];
    const existing = channels[reading.channel];
    if (existing === undefined) {
      channels[reading.channel] = { count: 1, min: reading.millivolts, max: reading.millivolts, worst: label };
      continue;
    }
    existing.count += 1;
    existing.min = Math.min(existing.min, reading.millivolts);
    existing.max = Math.max(existing.max, reading.millivolts);
    if (rankOf(label) > rankOf(existing.worst)) {
      existing.worst = label;
    }
  }
  return channels;
}

function buildReport(readingCount: number, channelCount: number, alertCount: number, labels: string[]): string {
  let worst = "standby";
  for (const label of labels) {
    if (rankOf(label) > rankOf(worst)) {
      worst = label;
    }
  }
  return "readings=" + readingCount + ";channels=" + channelCount + ";alerts=" + alertCount + ";worst=" + worst;
}

