type OrderStatus = "reserved" | "backordered" | "shipped" | "partial" | "cancelled" | "expired";

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

const STATUSES: OrderStatus[] = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

const badStr = (value: unknown): boolean => typeof value !== "string" || value.length === 0;
const badQty = (value: unknown): boolean => typeof value !== "number" || !Number.isInteger(value) || value < 1;
const onHand = (stock: Record<string, number>, item: string): number => stock[item] ?? 0;

const failure = (message: string): FulfillmentResult => ({ ok: false, error: message });

interface State {
  stock: Record<string, number>;
  orders: Record<string, OrderStatus>;
  reserved: Record<string, { item: string; qty: number }>;
  pendingWants: Record<string, { item: string; qty: number }>;
  queue: string[];
  rejected: number;
}

const newState = (stock: Record<string, number>): State => ({
  stock,
  orders: {},
  reserved: {},
  pendingWants: {},
  queue: [],
  rejected: 0,
});

const fulfillQueue = (state: State): void => {
  for (let index = 0; index < state.queue.length; index++) {
    const id = state.queue[index];
    const want = state.pendingWants[id];
    const inventory = onHand(state.stock, want.item);
    if (inventory >= want.qty) {
      state.stock[want.item] = inventory - want.qty;
      state.reserved[id] = { item: want.item, qty: want.qty };
      state.orders[id] = "reserved";
      delete state.pendingWants[id];
      state.queue.splice(index, 1);
      index = index - 1;
    }
  }
};

const releaseReservation = (state: State, id: string, status: Exclude<OrderStatus, "reserved" | "backordered" | "partial">): void => {
  const holding = state.reserved[id];
  state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
  delete state.reserved[id];
  state.orders[id] = status;
  fulfillQueue(state);
};

interface Context {
  state: State;
  index: number;
}

const orderEvent = (ctx: Context, input: Record<string, unknown>): FulfillmentResult | undefined => {
  const { state, index } = ctx;
  const message = `event ${index}: `;
  if (badStr(input.id)) return failure(message + "bad id");
  if (state.orders[input.id as string] !== undefined) return failure(message + "duplicate order");
  if (badStr(input.item)) return failure(message + "bad item");
  if (badQty(input.qty)) return failure(message + "bad qty");
  const id = input.id as string;
  const item = input.item as string;
  const qty = input.qty as number;
  if (onHand(state.stock, item) >= qty) {
    state.stock[item] = onHand(state.stock, item) - qty;
    state.reserved[id] = { item, qty };
    state.orders[id] = "reserved";
  } else {
    state.queue.push(id);
    state.pendingWants[id] = { item, qty };
    state.orders[id] = "backordered";
  }
};

const cancelEvent = (ctx: Context, input: Record<string, unknown>): FulfillmentResult | undefined => {
  const { state, index } = ctx;
  if (badStr(input.id)) return failure(`event ${index}: bad id`);
  const id = input.id as string;
  if (state.reserved[id] !== undefined) {
    releaseReservation(state, id, "cancelled");
  } else if (state.orders[id] === "backordered") {
    state.queue.splice(state.queue.indexOf(id), 1);
    delete state.pendingWants[id];
    state.orders[id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
};

const shipEvent = (ctx: Context, input: Record<string, unknown>): FulfillmentResult | undefined => {
  const { state, index } = ctx;
  const message = `event ${index}: `;
  if (badStr(input.id)) return failure(message + "bad id");
  if (input.qty !== undefined && badQty(input.qty)) return failure(message + "bad qty");
  const id = input.id as string;
  const holding = state.reserved[id];
  if (holding === undefined) {
    state.rejected = state.rejected + 1;
  } else if (input.qty === undefined || input.qty === holding.qty) {
    delete state.reserved[id];
    state.orders[id] = "shipped";
  } else if ((input.qty as number) < holding.qty) {
    state.reserved[id] = { item: holding.item, qty: holding.qty - (input.qty as number) };
    state.orders[id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
};

const restockEvent = (ctx: Context, input: Record<string, unknown>): FulfillmentResult | undefined => {
  const { state, index } = ctx;
  const message = `event ${index}: `;
  if (badStr(input.item)) return failure(message + "bad item");
  if (badQty(input.qty)) return failure(message + "bad qty");
  const item = input.item as string;
  state.stock[item] = onHand(state.stock, item) + (input.qty as number);
  fulfillQueue(state);
};

const expireEvent = (ctx: Context, input: Record<string, unknown>): FulfillmentResult | undefined => {
  const { state, index } = ctx;
  if (badStr(input.id)) return failure(`event ${index}: bad id`);
  const id = input.id as string;
  if (state.reserved[id] !== undefined) {
    releaseReservation(state, id, "expired");
  } else {
    state.rejected = state.rejected + 1;
  }
};

type EventHandler = (ctx: Context, input: Record<string, unknown>) => FulfillmentResult | undefined;

const handlers: Record<string, EventHandler> = {
  order: orderEvent,
  cancel: cancelEvent,
  ship: shipEvent,
  restock: restockEvent,
  expire: expireEvent,
};

function parseInput(raw: unknown): { state: State; error?: string } {
  if (typeof raw !== "object" || raw === null) {
    return { state: newState({}), error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { state: newState({}), error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  for (const item of Object.keys(input.stock as Record<string, unknown>)) {
    const level = (input.stock as Record<string, unknown>)[item];
    if (typeof level !== "number" || !Number.isInteger(level) || level < 0) {
      return { state: newState({}), error: "bad stock" };
    }
    stock[item] = level;
  }
  if (!Array.isArray(input.events)) {
    return { state: newState({}), error: "bad events" };
  }
  return { state: newState(stock) };
}

export function processEvents(raw: unknown): FulfillmentResult {
  const parsed = parseInput(raw);
  if (parsed.error !== undefined) {
    return failure(parsed.error);
  }
  const ctx: Context = { state: parsed.state, index: 0 };
  const events = (raw as Record<string, unknown>).events as unknown[];
  for (ctx.index = 0; ctx.index < events.length; ctx.index++) {
    const event = events[ctx.index];
    if (typeof event !== "object" || event === null) {
      return failure(`event ${ctx.index}: malformed`);
    }
    const handler = handlers[(event as Record<string, unknown>).type as string];
    if (handler === undefined) {
      return failure(`event ${ctx.index}: bad type`);
    }
    const outcome = handler(ctx, event as Record<string, unknown>);
    if (outcome !== undefined) {
      return outcome;
    }
  }
  return {
    ok: true,
    orders: ctx.state.orders,
    stock: ctx.state.stock,
    queue: ctx.state.queue,
    rejected: ctx.state.rejected,
    report: buildReport(ctx.state.orders, ctx.state.rejected),
  };
}

function statusCounts(orders: Record<string, OrderStatus>): Record<OrderStatus, number> {
  const counts = STATUSES.reduce(
    (acc, status) => {
      acc[status] = 0;
      return acc;
    },
    {} as Record<OrderStatus, number>,
  );
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, OrderStatus>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

