import { readFileSync } from 'node:fs';
const orig = readFileSync('process_events.orig.ts','utf8');
const cur = readFileSync('process_events.ts','utf8');
function count(code){
  // strip line/block comments reasonably
  code = code.replace(/\/\*[\s\S]*?\*\//g,'').replace(/\/\/[^\n]*/g,'');
  let n=0;
  // count keywords and operators
  n += (code.match(/\bif\b/g)||[]).length;
  n += (code.match(/\belse\b/g)||[]).length;
  n += (code.match(/\?/g)||[]).length; // ternary & optional chaining
  n += (code.match(/\bcase\b/g)||[]).length;
  n += (code.match(/\bcatch\b/g)||[]).length;
  n += (code.match(/\?\./g)||[]).length;
  // logical operators
  n += (code.match(/&&/g)||[]).length;
  n += (code.match(/\|\|/g)||[]).length;
  n += (code.match(/\?\?/g)||[]).length;
  return n;
}
