import { processEvents as orig } from './process_events.orig.ts';
import { processEvents as mine } from './process_events.ts';
import { deepStrictEqual } from 'node:assert';

let seed = 12345;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
const ri = (n) => Math.floor(rnd() * n);
const pick = (a) => a[ri(a.length)];

const items = ['apple', 'banana', 'pear'];
const ids = ['a','b','c','d','e','f','g','h','i','j'];

function genInput() {
  const stock = {};
  const nStock = ri(3);
  for (let i = 0; i < nStock; i++) stock[pick(items)] = ri(8);
  const n = 1 + ri(25);
  const events = [];
  for (let i = 0; i < n; i++) {
    const t = pick(['order','order','order','cancel','ship','ship','restock','expire','order','ship']);
    const id = pick(ids);
    const item = pick(items);
    const qty = 1 + ri(6);
    if (t === 'order') events.push({type:'order', id, item, qty});
    else if (t === 'cancel') events.push({type:'cancel', id});
    else if (t === 'ship') events.push(rnd()<0.4 ? {type:'ship', id} : {type:'ship', id, qty: 1+ri(5)});
    else if (t === 'restock') events.push({type:'restock', item, qty});
    else events.push({type:'expire', id});
  }
  return { stock, events };
}

// also test malformed/error inputs
function genBad() {
  const kind = ri(10);
  if (kind===0) return null;
  if (kind===1) return 42;
  if (kind===2) return { stock: 5, events: [] };
  if (kind===3) return { stock: {}, events: 'x' };
  if (kind===4) return { stock: {a:-1}, events: [] };
  if (kind===5) return { stock: {a:1.5}, events: [] };
  if (kind===6) return { stock: {}, events: [null] };
  if (kind===7) return { stock: {}, events: [{type:'order', id:'', item:'x', qty:1}] };
  if (kind===8) return { stock: {}, events: [{type:'order', id:'a', item:'', qty:1}] };
  if (kind===9) return { stock: {}, events: [{type:'order', id:'a', item:'x', qty:0}] };
  return { stock: {}, events: [] };
}

let fails = 0;
for (let iter = 0; iter < 20000; iter++) {
  const input = rnd() < 0.3 ? genBad() : genInput();
  let a, b;
  try { a = orig(structuredClone(input)); } catch(e){ a = {__throw: String(e)}; }
  try { b = mine(structuredClone(input)); } catch(e){ b = {__throw: String(e)}; }
  try { deepStrictEqual(a, b); }
  catch(e) {
    fails++;
    if (fails <= 5) { console.log('MISMATCH on', JSON.stringify(input)); console.log('orig', JSON.stringify(a)); console.log('mine', JSON.stringify(b)); }
  }
}
console.log('done, fails =', fails);

