  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts?: string[];
  report?: string;
}

const MAX_READINGS = 500;
const UNITS = ["uV", "mV", "V"] as const;
type Unit = (typeof UNITS)[number];

export function processBatch(raw: unknown): BatchResult {
  const readings = extractReadings(raw);
  if (readings === null) {
    return { ok: false, error: batchError(raw) };
  }

  const labels: string[] = new Array(readings.length);
  const alerts: string[] = [];
  const channels: Record<string, ChannelSummary> = {};
  let worst = "standby";

  for (let index = 0; index < readings.length; index++) {
    const outcome = parseReading(readings[index], index);
    if (typeof outcome === "string") {
      return { ok: false, error: outcome };
    }

    const millivolts = normalizeValue(outcome.unit, outcome.value);
    const label = classifySignal(millivolts);

    labels[index] = label;
    if (severityRank(label) > severityRank(worst)) {
      worst = label;
    }

    const alert = alertForReading(outcome.channel, millivolts);
    if (alert !== null) {
      alerts.push(alert);
    }

    updateChannelSummary(channels, outcome.channel, millivolts, label);
  }

  const report = buildReport(readings.length, Object.keys(channels).length, alerts.length, worst);
  return { ok: true, readings: readings.length, labels, channels, alerts, report };
}

function extractReadings(raw: unknown): unknown[] | null {
  if (!isRecord(raw)) {
    return null;
  }
  const readings = raw.readings;
  if (!Array.isArray(readings)) {
    return null;
  }
  if (readings.length === 0 || readings.length > MAX_READINGS) {
    return null;
  }
  return readings;
}

function batchError(raw: unknown): string {
  if (!isRecord(raw)) {
    return "malformed batch";
  }
  const readings = raw.readings;
  if (!Array.isArray(readings)) {
    return "missing readings";
  }
  if (readings.length > MAX_READINGS) {
    return "batch too large";
  }
  return "empty batch";
}

function parseReading(entry: unknown, index: number): Reading | string {
  if (!isRecord(entry)) {
    return "reading " + index + ": malformed";
  }
  if (typeof entry.channel !== "string" || entry.channel.length === 0) {
    return "reading " + index + ": bad channel";
  }
  if (!isUnit(entry.unit)) {
    return "reading " + index + ": bad unit";
  }
  if (!Number.isInteger(entry.value)) {
    return "reading " + index + ": bad value";
  }
  if (!isNonNegativeInt(entry.at)) {
    return "reading " + index + ": bad timestamp";
  }
  return {
    channel: entry.channel,
    unit: entry.unit as Unit,
    value: entry.value as number,
    at: entry.at as number,
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function isUnit(value: unknown): value is Unit {
  return (UNITS as readonly string[]).includes(value as string);
}

function isNonNegativeInt(value: unknown): boolean {
  return Number.isInteger(value) && (value as number) >= 0;
}

function normalizeValue(unit: string, value: number): number {
  if (unit === "V") {
    return value * 1000;
  }
  if (unit === "uV") {
    return Math.trunc(value / 1000);
  }
  return value;
}

export function classifySignal(millivolts: number): string {
  if (millivolts >= 0 && millivolts < 50) {
    return "standby";
  }
  if (millivolts >= 50 && millivolts < 200) {
    return "idle";
  }
  if (millivolts >= 200 && millivolts < 600) {
    return "active";
  }
  if (millivolts >= 600 && millivolts < 900) {
    return "loaded";
  }
  if (millivolts >= 900) {
    return "critical";
  }
  return "negative";
}

function severityRank(label: string): number {
  switch (label) {
    case "negative":
      return 5;
    case "critical":
      return 4;
    case "loaded":
      return 3;
    case "active":
      return 2;
    case "idle":
      return 1;
    default:
      return 0;
  }
}

function alertForReading(channel: string, millivolts: number): string | null {
  if (millivolts >= 900) {
    return channel + ":critical";
  }
  if (millivolts < 0) {
    return channel + ":negative";
  }
  if (millivolts >= 600) {
    return channel + ":loaded";
  }
  return null;
}

function updateChannelSummary(
  channels: Record<string, ChannelSummary>,
  channel: string,
  millivolts: number,
  label: string,
): void {
  const existing = channels[channel];
  if (existing === undefined) {
    channels[channel] = { count: 1, min: millivolts, max: millivolts, worst: label };
    return;
  }
  existing.count = existing.count + 1;
  if (millivolts < existing.min) {
    existing.min = millivolts;
  }
  if (millivolts > existing.max) {
    existing.max = millivolts;
  }
  if (severityRank(label) > severityRank(existing.worst)) {
    existing.worst = label;
  }
}

function buildReport(readingCount: number, channelCount: number, alertCount: number, worst: string): string {
  return "readings=" + readingCount + ";channels=" + channelCount + ";alerts=" + alertCount + ";worst=" + worst;
}

