}

interface SignalBand {
  label: string;
  min: number;
  max: number;
  severity: number;
  alert: boolean;
}

interface BatchAnalysis {
  labels: string[];
  alerts: string[];
  channels: Record<string, ChannelSummary>;
  worstLabel: string;
}

const MAX_READINGS = 500;
const UNITS = ["uV", "mV", "V"];

type Normalizer = (value: number) => number;
const NORMALIZE: Record<string, Normalizer> = {
  V: (value) => value * 1000,
  uV: (value) => Math.trunc(value / 1000),
};

const STANDBY: SignalBand = { label: "standby", min: 0, max: 50, severity: 0, alert: false };
const IDLE: SignalBand = { label: "idle", min: 50, max: 200, severity: 1, alert: false };
const ACTIVE: SignalBand = { label: "active", min: 200, max: 600, severity: 2, alert: false };
const LOADED: SignalBand = { label: "loaded", min: 600, max: 900, severity: 3, alert: true };
const CRITICAL: SignalBand = { label: "critical", min: 900, max: Infinity, severity: 4, alert: true };
const NEGATIVE: SignalBand = { label: "negative", min: -Infinity, max: 0, severity: 5, alert: true };

const BANDS: SignalBand[] = [STANDBY, IDLE, ACTIVE, LOADED, CRITICAL, NEGATIVE];
const SEVERITY: Record<string, number> = Object.fromEntries(
  BANDS.map((band) => [band.label, band.severity])
);

function signalBand(millivolts: number): SignalBand {
  return BANDS.find((band) => millivolts >= band.min && millivolts < band.max) ?? NEGATIVE;
}

function normalizeValue(unit: string, value: number): number {
  return (NORMALIZE[unit] ?? ((v: number) => v))(value);
}

export function processBatch(raw: unknown): BatchResult {
  const batchError = validateBatch(raw);
  if (batchError !== null) {
    return { ok: false, error: batchError };
  }
  const parsed = parseReadings((raw as { readings: unknown[] }).readings);
  if (typeof parsed === "string") {
    return { ok: false, error: parsed };
  }
  const analysis = analyze(parsed);
  const report = buildReport(
    parsed.length,
    Object.keys(analysis.channels).length,
    analysis.alerts.length,
    analysis.worstLabel
  );
  return {
    ok: true,
    readings: parsed.length,
    labels: analysis.labels,
    channels: analysis.channels,
    alerts: analysis.alerts,
    report,
  };
}

function validateBatch(raw: unknown): string | null {
  if (typeof raw !== "object" || raw === null) {
    return "malformed batch";
  }
  const batch = raw as Record<string, unknown>;
  if (!Array.isArray(batch.readings)) {
    return "missing readings";
  }
  if (batch.readings.length === 0) {
    return "empty batch";
  }
  if (batch.readings.length > MAX_READINGS) {
    return "batch too large";
  }
  return null;
}

function parseReadings(entries: unknown[]): ParsedReading[] | string {
  const parsed: ParsedReading[] = [];
  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
    if (typeof outcome === "string") {
      return outcome;
    }
    parsed.push({
      channel: outcome.channel,
      millivolts: normalizeValue(outcome.unit, outcome.value),
      at: outcome.at,
    });
  }
  return parsed;
}

function parseReading(entry: unknown, index: number): Reading | string {
  if (typeof entry !== "object" || entry === null) {
    return "reading " + index + ": malformed";
  }
  const record = entry as Record<string, unknown>;
  if (typeof record.channel !== "string" || record.channel.length === 0) {
    return "reading " + index + ": bad channel";
  }
  if (UNITS.indexOf(record.unit as string) < 0) {
    return "reading " + index + ": bad unit";
  }
  if (!Number.isInteger(record.value)) {
    return "reading " + index + ": bad value";
  }
  if (!isNonNegativeInt(record.at)) {
    return "reading " + index + ": bad timestamp";
  }
  return {
    channel: record.channel,
    unit: record.unit as string,
    value: record.value as number,
    at: record.at as number,
  };
}

function analyze(parsed: ParsedReading[]): BatchAnalysis {
  const labels: string[] = [];
  const alerts: string[] = [];
  const channels: Record<string, ChannelSummary> = {};
  let worstSeverity = 0;
  let worstLabel = STANDBY.label;

  for (const reading of parsed) {
    const band = signalBand(reading.millivolts);
    labels.push(band.label);
    if (band.alert) {
      alerts.push(reading.channel + ":" + band.label);
    }
    recordChannel(channels, reading, band);
    if (band.severity > worstSeverity) {
      worstSeverity = band.severity;
      worstLabel = band.label;
    }
  }
  return { labels, alerts, channels, worstLabel };
}

function recordChannel(
  channels: Record<string, ChannelSummary>,
  reading: ParsedReading,
  band: SignalBand
): void {
  const existing = channels[reading.channel];
  if (existing === undefined) {
    channels[reading.channel] = {
      count: 1,
      min: reading.millivolts,
      max: reading.millivolts,
      worst: band.label,
    };
    return;
  }
  existing.count = existing.count + 1;
  existing.min = Math.min(existing.min, reading.millivolts);
  existing.max = Math.max(existing.max, reading.millivolts);
  if (band.severity > SEVERITY[existing.worst]) {
    existing.worst = band.label;
  }
}

function isNonNegativeInt(value: unknown): boolean {
  return Number.isInteger(value) && (value as number) >= 0;
}

export function classifySignal(millivolts: number): string {
  return signalBand(millivolts).label;
}

function buildReport(
  readingCount: number,
  channelCount: number,
  alertCount: number,
  worstLabel: string
): string {
  return (
    "readings=" +
    readingCount +
    ";channels=" +
    channelCount +
    ";alerts=" +
    alertCount +
    ";worst=" +
    worstLabel
  );
}
